window.BioDrillNew = {"28":[{"id":"D28-1","topic":0,"q":"Give two ways the nasal cavity prepares the air before it reaches the lungs.","marks":6,"need":2,"pts":[{"a":"Filters it: hairs and mucus trap dust and microbes","accept":["cleans the air","hairs trap dust","mucus catches germs","removes dust from the air"],"k":[{"w":["filter"],"n":1},{"w":["clean"],"n":1},{"w":["trap"],"n":1},{"w":["catch"],"n":1},{"w":["remov","dust"],"n":2},{"w":["remov","germ"],"n":2},{"w":["remov","microb"],"n":2}]},{"a":"Warms it","accept":["heats the air","brings it to body temperature"],"k":[{"w":["warm"],"n":1},{"w":["heat"],"n":1},{"w":["body","temperatur"],"n":2}]},{"a":"Moistens it","accept":["makes it damp","adds water vapour","humidifies the air","makes the air wet"],"k":[{"w":["moist"],"n":1},{"w":["damp"],"n":1},{"w":["wet"],"n":1},{"w":["humid"],"n":1},{"w":["water","vapour"],"n":2},{"w":["add","water"],"n":2}]}],"right":"It filters, warms and moistens the air","wrong":["It cools the air and dries it out","It adds oxygen and removes carbon dioxide","It warms the air and pumps it into the lungs"],"why":"Hairs and mucus in the nasal cavity trap dust and germs, and its warm, moist lining warms and moistens the air, so clean, warm, moist air reaches the lungs."},{"id":"D28-2","topic":0,"q":"State the function of the hairs inside the nose.","marks":3,"need":1,"pts":[{"a":"Filter the air: they trap dust and microbes","accept":["trap dust","stop dust getting into the lungs","catch germs","filter out large particles","clean the air"],"k":[{"w":["filter"],"n":1},{"w":["trap"],"n":1},{"w":["catch"],"n":1},{"w":["clean"],"n":1},{"w":["stop","dust"],"n":2},{"w":["stop","germ"],"n":2},{"w":["stop","microb"],"n":2},{"w":["remov","dust"],"n":2}]}],"right":"They trap dust and germs, filtering the air","wrong":["They warm the air before it reaches the lungs","They sweep mucus up to the throat","They detect smells in the air"],"why":"The hairs inside the nostrils act like a filter: they trap dust and microbes in the air breathed in, so less of it reaches the lungs."},{"id":"D28-3","topic":0,"q":"Suggest why breathing through the nose is better for the lungs than breathing through the mouth.","marks":3,"need":1,"pts":[{"a":"The air is filtered, warmed and moistened in the nose, but not in the mouth","accept":["the nose cleans the air","the air is warmed","the nose traps dust and germs","the air is moistened","the air is made damp"],"k":[{"w":["filter"],"n":1},{"w":["warm"],"n":1},{"w":["moist"],"n":1},{"w":["clean"],"n":1},{"w":["trap"],"n":1},{"w":["heat"],"n":1},{"w":["damp"],"n":1},{"w":["humid"],"n":1}]}],"right":"The nose filters, warms and moistens the air but the mouth does not","wrong":["More oxygen can pass through the nose than the mouth","The nose has alveoli that start gas exchange","The epiglottis only works when you breathe through the nose"],"why":"Only the nasal cavity has hairs, mucus and a warm, moist lining, so air breathed in through the nose reaches the lungs cleaner, warmer and moister."},{"id":"D28-4","topic":1,"q":"State the function of the mucus that lines the trachea.","marks":3,"need":1,"pts":[{"a":"It traps dust and microbes (germs)","accept":["catches dirt and bacteria","traps particles","stops germs reaching the lungs","dust sticks to it"],"k":[{"w":["trap"],"n":1},{"w":["catch"],"n":1},{"w":["filter"],"n":1},{"w":["stop","dust"],"n":2},{"w":["stop","germ"],"n":2},{"w":["stop","microb"],"n":2},{"w":["stop","bacteri"],"n":2},{"w":["stick","dust"],"n":2},{"w":["stick","germ"],"n":2},{"w":["stick","dirt"],"n":2}]}],"right":"It traps dust and germs in the air breathed in","wrong":["It keeps the trachea open so it does not collapse","It sweeps dust up to the throat","It lubricates food on its way to the stomach"],"why":"Mucus is sticky: dust and microbes in the air breathed in get caught in it before they can reach the alveoli. The cilia then move it away."},{"id":"D28-5","topic":1,"q":"State the function of the cilia that line the trachea and bronchi.","marks":3,"need":1,"pts":[{"a":"They sweep (beat) the mucus and trapped dust up to the throat, away from the lungs","accept":["sweep mucus up to the throat","move mucus away from the lungs","beat to push mucus upwards","carry dirt up out of the airways","waft the mucus towards the mouth"],"k":[{"w":["mucus","up"],"n":2},{"w":["mucus","upward"],"n":2},{"w":["mucus","away"],"n":2},{"w":["mucus","throat"],"n":2},{"w":["mucus","mouth"],"n":2},{"w":["mucus","pharynx"],"n":2},{"w":["dust","up"],"n":2},{"w":["dirt","up"],"n":2},{"w":["dust","away"],"n":2},{"w":["dirt","away"],"n":2},{"w":["dust","throat"],"n":2},{"w":["sweep","up"],"n":2},{"w":["swept","up"],"n":2},{"w":["sweep","away"],"n":2},{"w":["sweep","throat"],"n":2},{"w":["beat","up"],"n":2},{"w":["push","up"],"n":2}]}],"right":"They sweep the mucus and trapped dust up, away from the lungs, to the throat","wrong":["They sweep dust down into the lungs","They trap dust in a sticky layer","They carry out gas exchange with the capillaries"],"why":"Cilia are tiny hairs on the lining cells. They beat to move mucus, with the dust and germs stuck in it, up to the throat, where it is swallowed or coughed up."},{"id":"D28-6","topic":1,"q":"Smoke damages the cilia in the airways. Suggest why smokers often cough.","marks":3,"need":1,"pts":[{"a":"Mucus is not swept away, so it builds up in the airways and has to be coughed up","accept":["mucus builds up in the lungs","mucus collects in the airways","the mucus stays in the bronchi","the mucus is not removed","to get rid of the mucus"],"k":[{"w":["mucus","build"],"n":2},{"w":["mucus","collect"],"n":2},{"w":["mucus","stay"],"n":2},{"w":["mucus","remov"],"n":2},{"w":["mucus","swept"],"n":2},{"w":["mucus","accumul"],"n":2},{"w":["mucus","clear"],"n":2}]}],"right":"Mucus is not swept away, so it builds up and must be coughed up","wrong":["The cilia beat faster and push the smoke into the lungs","Smoke makes the diaphragm contract more strongly","The smoke dissolves in the moist lining of the alveoli"],"why":"With damaged cilia, the mucus and the dirt and germs trapped in it are no longer swept up out of the airways. The mucus builds up, and coughing is the only way to clear it."},{"id":"D28-7","topic":1,"q":"Explain how the mucus and the cilia in the trachea together protect the lungs.","marks":6,"need":2,"pts":[{"a":"Mucus traps dust and microbes","accept":["the mucus catches germs","mucus traps bacteria and dirt","sticky mucus traps particles"],"k":[{"w":["mucus","trap"],"n":2},{"w":["mucus","catch"],"n":2},{"w":["mucus","dust"],"n":2},{"w":["mucus","microb"],"n":2},{"w":["mucus","germ"],"n":2},{"w":["mucus","bacteri"],"n":2},{"w":["mucus","dirt"],"n":2}]},{"a":"Cilia sweep the mucus up, away from the lungs, to the throat","accept":["the cilia beat to move mucus upwards","cilia carry the mucus to the throat to be swallowed","cilia push it away from the lungs"],"k":[{"w":["cilia","up"],"n":2},{"w":["cilia","upward"],"n":2},{"w":["cilia","away"],"n":2},{"w":["cilia","throat"],"n":2},{"w":["cilia","mouth"],"n":2},{"w":["cilia","pharynx"],"n":2},{"w":["cilia","swallow"],"n":2}]}],"right":"Mucus traps dust and germs, and cilia sweep the mucus up to the throat","wrong":["Cilia trap dust and mucus sweeps it down into the lungs","Mucus kills all the germs and cilia pump air into the lungs","Mucus moistens the air and cilia warm it"],"why":"Sticky mucus traps dust and microbes from the air. The cilia beat to carry this mucus up and away from the lungs to the throat, where it is swallowed."},{"id":"D28-8","topic":2,"q":"State the function of the bronchioles.","marks":3,"need":1,"pts":[{"a":"Carry air to (and from) the alveoli","accept":["take air into the air sacs","carry air from the bronchi to the alveoli","bring air to the alveoli for gas exchange"],"k":[{"w":["air","alveol"],"n":2},{"w":["air","sac"],"n":2}]}],"right":"They carry air from the bronchi to the alveoli","wrong":["They are where gas exchange takes place","They carry air from the larynx into the trachea","They make sounds as air passes over them"],"why":"The bronchioles are the many fine branches of each bronchus. They carry air deep into the lung, right to the alveoli, where gas exchange takes place."},{"id":"D28-9","topic":2,"q":"The pharynx is part of both the breathing system and the digestive system. Explain why.","marks":3,"need":1,"pts":[{"a":"Both air and food pass through it","accept":["air goes through it to the larynx and food goes through it to the oesophagus","food and air both travel through the throat","it carries air and food"],"k":[{"w":["air","food"],"n":2},{"w":["air","swallow"],"n":2}]}],"right":"Both air and food pass through the pharynx","wrong":["It makes sounds when air passes over it","It closes over the trachea when you swallow","It digests food and absorbs oxygen"],"why":"The pharynx (throat) is a shared passage: air goes through it on its way to the larynx, and food goes through it on its way to the oesophagus."},{"id":"D28-10","topic":2,"q":"Name the two structures that air passes through between the pharynx and the bronchi.","marks":6,"need":2,"pts":[{"a":"Larynx","accept":["voice box"],"k":[{"w":["larynx"],"n":1},{"w":["voice","box"],"n":2}]},{"a":"Trachea","accept":["windpipe"],"k":[{"w":["trachea"],"n":1},{"w":["windpipe"],"n":1}]}],"right":"The larynx and then the trachea","wrong":["The trachea and then the bronchioles","The epiglottis and then the oesophagus","The nasal cavity and then the larynx"],"why":"Air passes through the nasal cavity, pharynx, larynx (the voice box), trachea, bronchus and bronchioles, and finally reaches the alveoli."},{"id":"D28-11","topic":2,"q":"State the function of a bronchus.","marks":3,"need":1,"pts":[{"a":"Carries air from the trachea into a lung","accept":["takes air into the lung","carries air to the bronchioles","brings air from the windpipe into each lung","air passes through it into the lungs"],"k":[{"w":["carry","air","lung"],"n":3},{"w":["take","air","lung"],"n":3},{"w":["bring","air","lung"],"n":3},{"w":["transport","air","lung"],"n":3},{"w":["air","pass","lung"],"n":3},{"w":["air","into","lung"],"n":3},{"w":["air","bronchiol"],"n":2},{"w":["trachea","lung"],"n":2}]}],"right":"It carries air from the trachea into one lung","wrong":["It is where gas exchange takes place","It makes sounds as air passes over it","It stops food going into the trachea"],"why":"The trachea splits into two bronchi, one for each lung. Each bronchus carries air into its lung, where it branches into the bronchioles."},{"id":"D28-12","topic":2,"q":"Name the structures that air passes through just before it reaches the alveoli.","marks":3,"need":1,"pts":[{"a":"Bronchioles","accept":["the bronchioles"],"k":[{"w":["bronchiol"],"n":1}]}],"right":"The bronchioles","wrong":["The bronchi","The trachea","The capillaries"],"why":"Each bronchus branches again and again into tiny bronchioles, and each bronchiole ends in a bunch of alveoli, where gas exchange happens."},{"id":"D28-13","topic":3,"q":"What is meant by a concentration gradient?","marks":3,"need":1,"pts":[{"a":"A difference in the concentration of a substance between two regions","accept":["the difference in concentration between two areas","a concentration difference between two places"],"k":[{"w":["differ","concentr"],"n":2}]}],"right":"A difference in concentration between two regions","wrong":["The movement of molecules from high to low concentration","The total amount of a substance dissolved in a solution","The speed at which a gas diffuses across a membrane"],"why":"A concentration gradient is a difference in concentration between two places. Diffusion is movement down that gradient, so the steeper the gradient, the faster the diffusion."},{"id":"D28-14","topic":3,"q":"Explain how breathing helps to keep the concentration gradient of oxygen steep at the alveolus.","marks":3,"need":1,"pts":[{"a":"Each breath brings fresh air, high in oxygen, into the alveoli, replacing the used air","accept":["it keeps bringing in fresh air","new air keeps arriving","it replaces the air in the alveoli","it keeps the oxygen concentration in the alveoli high","it renews the air"],"k":[{"w":["fresh","air"],"n":2},{"w":["new","air"],"n":2},{"w":["renew","air"],"n":2},{"w":["replac","air"],"n":2},{"w":["oxygen","high","alveol"],"n":3},{"w":["more","oxygen","alveol"],"n":3}]}],"right":"It keeps bringing fresh air, high in oxygen, into the alveoli","wrong":["Breathing pumps oxygen across the alveolus wall into the blood","It keeps the oxygen level in the blood high","It makes the walls of the alveoli thinner"],"why":"Each breath replaces used air in the alveoli with fresh air, so the oxygen concentration there stays higher than in the blood, and oxygen keeps diffusing in."},{"id":"D28-15","topic":3,"q":"Explain how the flow of blood past the alveolus helps to keep the concentration gradient of oxygen steep.","marks":3,"need":1,"pts":[{"a":"Moving blood carries the oxygen away, so the blood arriving at the alveolus is always low in oxygen","accept":["the blood carries the oxygen away","oxygen is taken away to the body","new blood low in oxygen keeps arriving","deoxygenated blood keeps arriving from the pulmonary artery","the oxygen is removed by the blood"],"k":[{"w":["oxygen","away"],"n":2},{"w":["blood","low","oxygen"],"n":3},{"w":["deoxygen"],"n":1},{"w":["oxygen","remov"],"n":2}]}],"right":"It carries the oxygen away, so arriving blood is always low in oxygen","wrong":["Blood flows slowly so oxygen has more time to diffuse","Haemoglobin releases oxygen into the alveolus","Blood flows out of the capillaries into the alveolus"],"why":"Blood keeps carrying newly absorbed oxygen away to the body, so the blood in the capillary always has less oxygen than the air in the alveolus."},{"id":"D28-16","topic":3,"q":"Give two ways the concentration gradient of carbon dioxide is kept steep at the alveolus.","marks":6,"need":2,"pts":[{"a":"Blood keeps bringing carbon dioxide from the respiring body cells","accept":["the blood keeps bringing more CO2","blood from the pulmonary artery is high in carbon dioxide","the blood arriving is rich in CO2"],"k":[{"w":["bring","co2"],"n":2},{"w":["blood","high","co2"],"n":3},{"w":["blood","rich","co2"],"n":3},{"w":["blood","more","co2"],"n":3},{"w":["arriv","co2"],"n":2},{"w":["deliver","co2"],"n":2}]},{"a":"Breathing out removes the carbon dioxide from the alveolus","accept":["exhaling removes CO2 from the alveoli","CO2 is breathed out","the air in the alveoli is kept low in CO2"],"k":[{"w":["breath","out","co2"],"n":3},{"w":["exhal","co2"],"n":2},{"w":["remov","co2","alveol"],"n":3},{"w":["air","low","co2"],"n":3},{"w":["alveol","low","co2"],"n":3}]}],"right":"Blood keeps bringing CO2 to the lungs, and breathing out removes it","wrong":["Haemoglobin carries carbon dioxide into the alveolus","The alveoli make carbon dioxide and pass it to the blood","Breathing in fresh oxygen pushes carbon dioxide into the blood"],"why":"Respiring cells keep adding carbon dioxide to the blood that comes to the lungs, while breathing out keeps the level in the alveolus low, so it keeps diffusing out of the blood."},{"id":"D28-17","topic":3,"q":"Suggest why gas exchange in the lungs slows down if breathing stops.","marks":3,"need":1,"pts":[{"a":"The air in the alveoli is not renewed, so the concentration gradients become less steep (oxygen is used up and carbon dioxide builds up in the alveoli)","accept":["the concentration gradient gets smaller","no fresh air reaches the alveoli","carbon dioxide builds up in the alveoli","the oxygen in the alveoli gets used up","the difference in concentration falls"],"k":[{"w":["gradient","less"],"n":2},{"w":["gradient","small"],"n":2},{"w":["gradient","decreas"],"n":2},{"w":["gradient","shallow"],"n":2},{"w":["no","fresh","air"],"n":3},{"w":["air","not","renew"],"n":3},{"w":["air","not","replac"],"n":3},{"w":["co2","build","alveol"],"n":3},{"w":["oxygen","used","alveol"],"n":3},{"w":["differ","concentr","decreas"],"n":3},{"w":["differ","concentr","small"],"n":3}]}],"right":"No fresh air arrives, so the concentration gradients become less steep","wrong":["The alveoli collapse and lose their large surface area","The walls of the alveoli become thicker","Oxygen can only diffuse while the diaphragm is moving"],"why":"Without breathing, the oxygen in the alveoli is used up and carbon dioxide builds up, so the difference in concentration between air and blood shrinks and diffusion slows."},{"id":"D28-18","topic":4,"q":"State the effect of a rise in carbon dioxide on the pH of the blood.","marks":3,"need":1,"pts":[{"a":"The pH falls (decreases): the blood becomes more acidic","accept":["the pH decreases","it lowers the pH","the blood gets more acidic","pH drops","the pH goes down","it causes acidosis"],"k":[{"w":["ph","decreas"],"n":2},{"w":["ph","lower"],"n":2},{"w":["ph","low"],"n":2},{"w":["ph","down"],"n":2},{"w":["more","acid"],"n":2},{"w":["acid","increas"],"n":2},{"w":["acidos"],"n":1}]}],"right":"The pH of the blood falls: it becomes more acidic","wrong":["The pH rises, making the blood more alkaline","It has no effect: the pH stays at 7.4","Carbon dioxide is carried as hydrogencarbonate, so the pH rises"],"why":"Carbon dioxide forms an acid when it dissolves in the water of the blood, so more carbon dioxide makes the blood more acidic: its pH falls."},{"id":"D28-19","topic":4,"q":"State what the medulla oblongata does when it detects a rise in carbon dioxide in the blood.","marks":3,"need":1,"pts":[{"a":"Sends nerve impulses to the diaphragm and intercostal muscles","accept":["sends impulses to the breathing muscles","sends messages along nerves to the diaphragm","signals the intercostal muscles to contract faster"],"k":[{"w":["impuls"],"n":1},{"w":["nerve"],"n":1},{"w":["message","muscle"],"n":2},{"w":["signal","muscle"],"n":2},{"w":["message","diaphragm"],"n":2},{"w":["signal","diaphragm"],"n":2},{"w":["message","intercost"],"n":2},{"w":["signal","intercost"],"n":2}]},{"a":"Makes breathing faster and deeper","accept":["it increases the breathing rate","it makes us breathe more deeply","makes you breathe quicker"],"k":[{"w":["breath","fast"],"n":2},{"w":["breath","deep"],"n":2},{"w":["breath","rate","increas"],"n":3},{"w":["breath","rapid"],"n":2}]}],"right":"It sends nerve impulses to the diaphragm and intercostal muscles","wrong":["It releases a hormone into the blood to open the airways","It makes the heart pump more oxygen to the lungs","It slows breathing down to save energy"],"why":"The medulla oblongata is the brain's breathing centre. It sends impulses along nerves to the diaphragm and intercostal muscles, so they contract faster and more strongly."},{"id":"D28-20","topic":4,"q":"Explain how the extra carbon dioxide made during exercise leads to faster breathing.","marks":6,"need":2,"pts":[{"a":"It makes the blood more acidic (its pH falls)","accept":["the pH of the blood decreases","the blood is more acidic","it lowers the pH of the blood"],"k":[{"w":["ph","decreas"],"n":2},{"w":["ph","lower"],"n":2},{"w":["ph","low"],"n":2},{"w":["ph","down"],"n":2},{"w":["more","acid"],"n":2},{"w":["acid","increas"],"n":2},{"w":["acidos"],"n":1}]},{"a":"This is detected by the medulla oblongata in the brain","accept":["the brain detects it","the medulla notices the change"],"k":[{"w":["medulla"],"n":1},{"w":["oblongata"],"n":1},{"w":["brain","detect"],"n":2}]},{"a":"Nerve impulses are sent to the diaphragm and intercostal muscles, which contract faster","accept":["impulses go to the breathing muscles","the brain sends messages to the diaphragm","nerves carry signals to the intercostal muscles"],"k":[{"w":["impuls"],"n":1},{"w":["nerve"],"n":1},{"w":["brain","message"],"n":2},{"w":["brain","signal"],"n":2},{"w":["message","muscle"],"n":2},{"w":["signal","muscle"],"n":2}]}],"right":"Blood pH falls; the medulla oblongata detects this and signals the diaphragm","wrong":["It lowers the oxygen level, which the heart detects","The medulla detects a rise in blood pH and slows the heart","Carbon dioxide makes the blood more acidic, so the lungs work harder"],"why":"Carbon dioxide makes the blood more acidic. The medulla oblongata detects the fall in pH and sends nerve impulses to the diaphragm and intercostal muscles, which contract faster and harder."},{"id":"D28-21","topic":4,"q":"Explain how faster, deeper breathing helps to bring the pH of the blood back to normal during exercise.","marks":3,"need":1,"pts":[{"a":"More carbon dioxide is breathed out (removed from the blood), so the blood becomes less acidic","accept":["it removes more CO2 from the blood","more carbon dioxide is exhaled","CO2 diffuses out of the blood faster and is breathed out","it gets rid of the extra carbon dioxide"],"k":[{"w":["remov","co2"],"n":2},{"w":["exhal","co2"],"n":2},{"w":["breath","out","co2"],"n":3},{"w":["co2","diffu","out"],"n":3},{"w":["less","co2"],"n":2},{"w":["lose","co2"],"n":2}]}],"right":"It removes carbon dioxide from the blood faster, by breathing it out","wrong":["It takes in more oxygen, which neutralises the acid","It makes the heart pump the acid to the kidneys","It cools the blood down so it is less acidic"],"why":"Breathing faster and deeper exhales the extra carbon dioxide, so less acid forms in the blood and its pH rises back towards normal."},{"id":"D28-22","topic":4,"q":"Suggest why a person who has held their breath for a long time then breathes quickly and deeply.","marks":3,"need":1,"pts":[{"a":"Carbon dioxide has built up in the blood, making it more acidic, and the medulla oblongata detects this","accept":["CO2 levels in the blood rise","the blood becomes more acidic","the pH of the blood falls","carbon dioxide builds up and must be removed","the brain detects high carbon dioxide"],"k":[{"w":["co2","build"],"n":2},{"w":["co2","increas"],"n":2},{"w":["co2","high"],"n":2},{"w":["more","co2"],"n":2},{"w":["co2","accumul"],"n":2},{"w":["more","acid"],"n":2},{"w":["acid","increas"],"n":2},{"w":["ph","decreas"],"n":2},{"w":["ph","low"],"n":2},{"w":["ph","lower"],"n":2},{"w":["ph","down"],"n":2}]}],"right":"Carbon dioxide has built up in the blood, making it more acidic","wrong":["The level of oxygen in the blood has fallen, and the brain detects this","The lungs have shrunk and need to be refilled","The heart has slowed down and needs to catch up"],"why":"While the breath is held, carbon dioxide from respiration builds up and the blood's pH falls. The medulla oblongata detects this and drives fast, deep breaths to remove it."}],"29":[{"id":"D29-1","topic":0,"q":"State the function of the urinary bladder.","marks":3,"need":1,"pts":[{"a":"Stores urine (until it is released through the urethra)","accept":["holds urine until it is released","keeps urine until you urinate","storage of urine"],"k":[{"w":["stor","urine"],"n":2},{"w":["hold","urine"],"n":2},{"w":["keep","urine"],"n":2}]}],"right":"It stores urine until it is released through the urethra.","wrong":["It makes urine by filtering the blood","It carries urine out of the body","It reabsorbs water from the urine"],"why":"The kidneys make urine all the time. The bladder holds it, so it can be released at a suitable time instead of trickling out constantly."},{"id":"D29-2","topic":0,"q":"Explain how urine is moved along the ureter to the bladder.","marks":3,"need":1,"pts":[{"a":"Peristalsis: waves of contraction of the muscle in the ureter wall","accept":["peristalsis","muscles in the ureter wall contract in waves","the muscle squeezes the urine along"],"k":[{"w":["peristal"],"n":1},{"w":["muscl","contract"],"n":2},{"w":["muscl","squeez"],"n":2}]}],"right":"By peristalsis: waves of contraction of the muscle in the ureter wall.","wrong":["It is pumped there by the blood pressure from the heart","By cilia that sweep the urine along the tube","By osmosis through the wall of the ureter"],"why":"Smooth muscle in the ureter wall contracts in waves (peristalsis), pushing urine down to the bladder, even when you are lying down."},{"id":"D29-3","topic":0,"q":"Name the ring of muscle that controls the release of urine from the bladder.","marks":3,"need":1,"pts":[{"a":"Sphincter (muscle)","accept":["sphincter muscle","the urethral sphincter"],"k":[{"w":["sphincter"],"n":1}]}],"right":"The sphincter muscle at the base of the bladder.","wrong":["The diaphragm","The muscle in the wall of the ureter","The muscles of the abdominal wall"],"why":"A sphincter is a ring of muscle. While it stays contracted it holds urine in the bladder; when it relaxes, urine flows out through the urethra."},{"id":"D29-4","topic":0,"q":"Give one feature of the wall of the urinary bladder that suits it to its function.","marks":3,"need":1,"pts":[{"a":"Elastic (stretchy) wall, so it expands as urine collects","accept":["it can stretch","the wall is elastic","it expands as it fills"],"k":[{"w":["elast"],"n":1},{"w":["stretch"],"n":1},{"w":["expand"],"n":1}]},{"a":"Muscular wall that contracts to push urine out","accept":["it has a muscular wall","muscle in the wall squeezes the urine out"],"k":[{"w":["muscl"],"n":1},{"w":["contract","urine"],"n":2}]}],"right":"Its wall is elastic, so it can stretch as it fills with urine.","wrong":["It has microvilli to give a large surface area","Its wall is one cell thick for fast diffusion","It is surrounded by capillaries to reabsorb water"],"why":"The bladder wall stretches as urine collects, so it can hold a lot, and its muscle contracts to push the urine out through the urethra."},{"id":"D29-5","topic":1,"q":"Name the part of the nephron where all the glucose is reabsorbed into the blood.","marks":3,"need":1,"pts":[{"a":"Proximal convoluted tubule (PCT)","accept":["proximal tubule","PCT"],"k":[{"w":["proxim"],"n":1},{"w":["pct"],"n":1}]}],"right":"The proximal convoluted tubule (PCT).","wrong":["The loop of Henle","The collecting duct","The distal convoluted tubule"],"why":"Everything useful comes back in the PCT, the first stretch after Bowman's capsule. The loop of Henle and DCT take back water and salts."},{"id":"D29-6","topic":1,"q":"State how glucose is reabsorbed in the proximal convoluted tubule.","marks":3,"need":1,"pts":[{"a":"Active transport","accept":["it is actively transported","active uptake"],"k":[{"w":["activ","transport"],"n":2},{"w":["activ","uptak"],"n":2}]}],"right":"By active transport, which uses energy from ATP.","wrong":["By osmosis, along with the water","By diffusion, with no energy used","By filtration under high pressure"],"why":"Glucose is pumped back into the blood against its concentration gradient so that none is lost in urine. This needs energy: active transport."},{"id":"D29-7","topic":1,"q":"Give two ways the cells lining the proximal convoluted tubule are adapted for reabsorption.","marks":6,"need":2,"pts":[{"a":"Microvilli (for a large surface area)","accept":["brush border","folded membrane for a large surface area"],"k":[{"w":["microvill"],"n":1},{"w":["large","surfac","area"],"n":3},{"w":["brush","border"],"n":2}]},{"a":"Many mitochondria (energy for active transport)","accept":["lots of mitochondria for energy","mitochondria to make ATP"],"k":[{"w":["mitochondri"],"n":1}]},{"a":"Close to many capillaries or lining one cell thick (short distance)","accept":["surrounded by capillaries","the lining is one cell thick"],"k":[{"w":["capillar"],"n":1},{"w":["one","cell","thick"],"n":3}]}],"right":"Microvilli give a large surface area; many mitochondria supply energy.","wrong":["They have cilia to sweep the filtrate along","They have thick walls and store glycogen","They are impermeable to water and have no nucleus"],"why":"Microvilli give a large surface area to take substances back, and many mitochondria make the ATP needed for active transport."},{"id":"D29-8","topic":1,"q":"Explain how water is reabsorbed from the loop of Henle.","marks":6,"need":2,"pts":[{"a":"By osmosis","accept":["osmosis","water moves out by osmosis"],"k":[{"w":["osmos"],"n":1}]},{"a":"The surrounding medulla is very salty (high salt concentration)","accept":["the medulla has a high salt concentration","salts are pumped out into the medulla","the tissue fluid around it is very salty"],"k":[{"w":["salt","medulla"],"n":2},{"w":["salt","high"],"n":2},{"w":["salt","surround"],"n":2},{"w":["salt","tissu","fluid"],"n":3},{"w":["concentr","medulla"],"n":2},{"w":["solute","high"],"n":2}]}],"right":"By osmosis, because the medulla around the loop is very salty.","wrong":["By active transport, using energy from ATP","By filtration, as the blood pressure is high","By diffusion of salts into the blood"],"why":"Salts pumped out of the ascending limb make the medulla very salty, so water leaves the descending limb by osmosis and returns to the blood."},{"id":"D29-9","topic":1,"q":"Explain why the cells lining the proximal convoluted tubule have many mitochondria.","marks":3,"need":1,"pts":[{"a":"To release energy (ATP) for active transport (of glucose and amino acids)","accept":["to make ATP for active transport","respiration supplies energy for reabsorption"],"k":[{"w":["energ","activ"],"n":2},{"w":["atp","activ"],"n":2},{"w":["energ","reabsorb"],"n":2},{"w":["atp","reabsorb"],"n":2},{"w":["energ","transport"],"n":2},{"w":["atp","transport"],"n":2},{"w":["respir","activ"],"n":2}]}],"right":"To release energy (ATP) for the active transport of glucose.","wrong":["To make urea from spare amino acids","To give a large surface area for diffusion","To store the glucose that is reabsorbed"],"why":"Mitochondria carry out aerobic respiration, making ATP. Taking glucose and amino acids back by active transport uses a lot of ATP."},{"id":"D29-10","topic":1,"q":"Explain why glucose must be reabsorbed by active transport rather than by diffusion.","marks":3,"need":1,"pts":[{"a":"Glucose moves against its concentration gradient (from low to high concentration)","accept":["it moves against the concentration gradient","against a gradient","up its concentration gradient"],"k":[{"w":["against","gradient"],"n":2},{"w":["against","concentr"],"n":2},{"w":["up","gradient"],"n":2}]},{"a":"So that all the glucose is reabsorbed and none is lost in urine","accept":["so none of the glucose is lost in the urine","so that all the glucose is taken back"],"k":[{"w":["all","glucose","reabsorb"],"n":3},{"w":["all","glucose","back"],"n":3},{"w":["none","urine"],"n":2},{"w":["no","glucose","urine"],"n":3}]}],"right":"It moves against its concentration gradient, so all of it is taken back.","wrong":["Glucose molecules are too large to diffuse through a membrane","Diffusion only works for gases like oxygen","Active transport needs no energy, so it is cheaper"],"why":"Diffusion would stop once the filtrate and blood had equal glucose levels, so some would be lost. Active transport pumps it all back, against the gradient."},{"id":"D29-11","topic":1,"q":"Other than water, name a substance reabsorbed from the loop of Henle.","marks":3,"need":1,"pts":[{"a":"Salts (or named, e.g. sodium chloride, sodium ions) or minerals","accept":["sodium ions","chloride","minerals","ions"],"k":[{"w":["salt"],"n":1},{"w":["sodium"],"n":1},{"w":["chlorid"],"n":1},{"w":["ion"],"n":1},{"w":["miner"],"n":1}]}],"right":"Salts, such as sodium chloride.","wrong":["Glucose, by active transport","Amino acids","Plasma proteins"],"why":"Salts are pumped out of the ascending limb into the medulla. Glucose and amino acids were all taken back earlier, in the PCT."},{"id":"D29-12","topic":2,"q":"What is meant by osmoregulation?","marks":3,"need":1,"pts":[{"a":"The control of the water and salt balance (concentration) of the body","accept":["regulating the water and salt content of the blood","keeping the water and salt concentration of body fluids constant","maintaining the water balance and salt balance"],"k":[{"w":["control","water","salt"],"n":3},{"w":["regul","water","salt"],"n":3},{"w":["keep","water","salt"],"n":3},{"w":["balanc","water","salt"],"n":3},{"w":["control","water","concentr"],"n":3},{"w":["regul","water","concentr"],"n":3},{"w":["keep","water","concentr"],"n":3},{"w":["control","water","balanc"],"n":3},{"w":["regul","water","balanc"],"n":3},{"w":["keep","water","balanc"],"n":3},{"w":["control","osmot","pressur"],"n":3},{"w":["regul","osmot","pressur"],"n":3}]}],"right":"The control of the water and salt balance of the body.","wrong":["The control of body temperature by sweating","The movement of water across a membrane by osmosis","The removal of the waste products of metabolism"],"why":"Osmoregulation is part of homeostasis: the kidneys, guided by ADH, keep the water and salt concentration of the blood steady."},{"id":"D29-13","topic":2,"q":"Name the organ that carries out osmoregulation in humans and the hormone that controls it.","marks":6,"need":2,"pts":[{"a":"Kidney","accept":["the kidneys","nephrons of the kidney"],"k":[{"w":["kidney"],"n":1},{"w":["nephron"],"n":1}]},{"a":"ADH (anti-diuretic hormone, vasopressin)","accept":["anti-diuretic hormone","antidiuretic hormone","vasopressin"],"k":[{"w":["adh"],"n":1},{"w":["anti","diuretic"],"n":2},{"w":["antidiuretic"],"n":1},{"w":["vasopressin"],"n":1}]}],"right":"The kidney, controlled by the hormone ADH.","wrong":["The liver, controlled by the hormone insulin","The skin, controlled by the hormone adrenaline","The kidney, controlled by the hormone thyroxine"],"why":"The kidneys control how much water and salt leave in urine. ADH, released by the pituitary gland, sets how much water they take back."},{"id":"D29-14","topic":2,"q":"Explain why osmoregulation is important for the cells of the body.","marks":3,"need":1,"pts":[{"a":"Stops cells gaining or losing too much water by osmosis (so they do not burst or shrink)","accept":["so cells do not burst or shrivel","so the cells do not lose or gain too much water by osmosis","so that cells don't swell up"],"k":[{"w":["cell","water","osmos"],"n":3},{"w":["cell","burst"],"n":2},{"w":["cell","shrink"],"n":2},{"w":["cell","swell"],"n":2},{"w":["cell","shrivel"],"n":2},{"w":["cell","lose","water"],"n":3},{"w":["cell","gain","water"],"n":3}]}],"right":"So cells do not gain or lose too much water by osmosis and burst or shrink.","wrong":["So that cells can make urea for excretion","So enzymes in the cells are not denatured by heat","So that cells get enough glucose for respiration"],"why":"If body fluids are too dilute, cells take in water by osmosis and swell; if too concentrated, they lose water and shrink. Either way they stop working well."},{"id":"D29-15","topic":2,"q":"Name two substances in the blood whose levels are controlled by osmoregulation.","marks":6,"need":2,"pts":[{"a":"Water","accept":["H2O"],"k":[{"w":["water"],"n":1}]},{"a":"Salts (or named, e.g. sodium chloride) or ions","accept":["sodium","ions","minerals","solutes"],"k":[{"w":["salt"],"n":1},{"w":["sodium"],"n":1},{"w":["ion"],"n":1},{"w":["miner"],"n":1},{"w":["solute"],"n":1}]}],"right":"Water and salts, such as sodium chloride.","wrong":["Glucose and insulin","Oxygen and carbon dioxide","Urea and amino acids"],"why":"Osmo- means water pressure: osmoregulation balances water against dissolved salts. Glucose is controlled by insulin, and gases by breathing."},{"id":"D29-16","topic":3,"q":"Name the part of the brain that detects that the blood has become too dilute.","marks":3,"need":1,"pts":[{"a":"Hypothalamus","accept":["receptors in the hypothalamus","osmoreceptors in the hypothalamus"],"k":[{"w":["hypothalamus"],"n":1}]}],"right":"The hypothalamus, using its osmoreceptors.","wrong":["The pituitary gland","The cerebellum","The medulla oblongata"],"why":"Osmoreceptors in the hypothalamus sense the water concentration of the blood. The hypothalamus then has the pituitary gland release less ADH."},{"id":"D29-17","topic":3,"q":"State the effect of drinking a large volume of water on the amount of ADH released.","marks":3,"need":1,"pts":[{"a":"Less ADH is released (by the pituitary gland)","accept":["ADH decreases","the level of ADH falls","less is secreted","a lower amount of ADH","it decreases"],"k":[{"w":["less","adh"],"n":2},{"w":["decreas","adh"],"n":2},{"w":["lower","adh"],"n":2},{"w":["low","adh"],"n":2},{"w":["less","releas"],"n":2},{"w":["less","secret"],"n":2},{"w":["decreas","releas"],"n":2},{"w":["decreas","secret"],"n":2},{"w":["decreas"],"n":1}]}],"right":"Less ADH is released by the pituitary gland.","wrong":["More ADH is released to remove the extra water","The kidneys release ADH instead of the pituitary","The amount of ADH stays the same"],"why":"Extra water makes the blood too dilute. The hypothalamus detects this, so the pituitary releases less ADH and the kidneys keep back less water."},{"id":"D29-18","topic":3,"q":"Explain how a low level of ADH affects the reabsorption of water in the collecting ducts.","marks":6,"need":2,"pts":[{"a":"The walls (of the collecting duct and DCT) become less permeable to water","accept":["the collecting duct becomes impermeable to water","permeability decreases"],"k":[{"w":["less","permeab"],"n":2},{"w":["impermeab"],"n":1},{"w":["decreas","permeab"],"n":2},{"w":["lower","permeab"],"n":2}]},{"a":"Less water is reabsorbed (into the blood)","accept":["more water stays in the tubule","less water goes back into the blood","less water is absorbed"],"k":[{"w":["less","water","reabsorb"],"n":3},{"w":["less","water","absorb"],"n":3},{"w":["decreas","water","reabsorb"],"n":3},{"w":["less","water","back"],"n":3},{"w":["water","stay","tubul"],"n":3},{"w":["water","stay","duct"],"n":3}]}],"right":"The walls become less permeable to water, so less water is reabsorbed.","wrong":["The walls become more permeable, so more water is reabsorbed","The walls actively pump glucose back into the blood","The walls become thicker, so more salt is filtered"],"why":"ADH opens the collecting duct walls to water. With little ADH they stay closed to it, so less water is taken back and more stays in the urine."},{"id":"D29-19","topic":3,"q":"State the effect on the urine of drinking a lot of water.","marks":6,"need":2,"pts":[{"a":"A large volume of urine","accept":["more urine is produced","lots of urine","an increased volume of urine"],"k":[{"w":["large","volum"],"n":2},{"w":["increas","volum"],"n":2},{"w":["high","volum"],"n":2},{"w":["more","urine","make"],"n":3},{"w":["lot","urine"],"n":2},{"w":["many","urine"],"n":2},{"w":["large","amount"],"n":2},{"w":["increas","amount"],"n":2}]},{"a":"Dilute urine","accept":["weak urine","less concentrated urine","pale urine"],"k":[{"w":["dilut"],"n":1},{"w":["weak"],"n":1},{"w":["pale"],"n":1},{"w":["less","concentr"],"n":2},{"w":["low","concentr"],"n":2},{"w":["lower","concentr"],"n":2}]}],"right":"A large volume of dilute urine is produced.","wrong":["A small volume of concentrated urine is produced","The urine contains glucose and protein","No change, as the extra water is stored in the bladder"],"why":"With less ADH, less water is taken back in the collecting ducts, so the extra water leaves as lots of dilute urine and the blood returns to normal."},{"id":"D29-20","topic":3,"q":"Explain why the control of ADH release is an example of negative feedback.","marks":3,"need":1,"pts":[{"a":"The response reverses (cancels) the change, bringing the blood back to normal","accept":["it brings the water concentration back to normal","the effect is opposite to the change","it corrects the change","it counteracts the change"],"k":[{"w":["revers"],"n":1},{"w":["opposit"],"n":1},{"w":["back","normal"],"n":2},{"w":["return","normal"],"n":2},{"w":["counteract"],"n":1},{"w":["cancel"],"n":1},{"w":["correct","change"],"n":2}]}],"right":"The response reverses the change, so the blood's water level returns to normal.","wrong":["The response makes the change bigger and bigger","ADH is released by a gland, not by a nerve","Less ADH is made when there is less glucose in the blood"],"why":"In negative feedback the response cancels the change: dilute blood means less ADH, so more water leaves in urine until the blood is back to normal."}],"30":[{"id":"D30-1","topic":0,"q":"What is meant by the term ingestion?","marks":3,"need":1,"pts":[{"a":"Taking in food (eating)","accept":["eating food","the intake of food","taking food into the mouth","consuming food","taking in nutrients"],"k":[{"w":["take","food"],"n":2},{"w":["eat","food"],"n":2},{"w":["intake","food"],"n":2},{"w":["take","nutrient"],"n":2},{"w":["eat","nutrient"],"n":2}]}],"right":"Ingestion is the taking in of food into the body.","wrong":["The breakdown of food into small soluble molecules","The passage of digested food into the blood","The removal of undigested food from the body"],"why":"Ingestion is taking food in through the mouth. It is the first step, followed by digestion, absorption and finally egestion."},{"id":"D30-2","topic":0,"q":"What is meant by absorption in the digestive system?","marks":3,"need":1,"pts":[{"a":"Digested food passing into the blood (or lymph)","accept":["the passage of digested food into the bloodstream","soluble food moving into the lymph","nutrients passing into the blood","food molecules taken into the blood"],"k":[{"w":["food","blood"],"n":2},{"w":["food","lymph"],"n":2},{"w":["nutrient","blood"],"n":2},{"w":["nutrient","lymph"],"n":2},{"w":["molecul","blood"],"n":2},{"w":["product","blood"],"n":2}]}],"right":"Absorption is the passage of digested food into the blood or lymph.","wrong":["The taking in of food through the mouth","The breakdown of large food molecules into small ones","The removal of undigested food from the body"],"why":"Absorption follows digestion: small soluble molecules pass through the gut wall, mostly in the villi of the ileum, into the blood or the lymph (lacteals)."},{"id":"D30-3","topic":0,"q":"Distinguish between ingestion and egestion.","marks":6,"need":2,"pts":[{"a":"Ingestion: taking in food","accept":["eating food","food is taken in through the mouth"],"k":[{"w":["take","food"],"n":2},{"w":["eat","food"],"n":2},{"w":["intake","food"],"n":2}]},{"a":"Egestion: removal of undigested food (faeces) from the body","accept":["getting rid of faeces through the anus","removing undigested waste","expelling unabsorbed material"],"k":[{"w":["undigest"],"n":1},{"w":["unabsorb"],"n":1},{"w":["faeces","remov"],"n":2},{"w":["faeces","leav"],"n":2},{"w":["faeces","anus"],"n":2},{"w":["faeces","expel"],"n":2}]}],"right":"Ingestion is taking in food; egestion is removing undigested food.","wrong":["Ingestion is digesting food; egestion is removing urea from cells","Ingestion is taking in food; egestion is removing waste made by cells","Ingestion is absorbing food; egestion is breaking food down"],"why":"Ingestion takes food in at the mouth. Egestion removes undigested food as faeces through the anus; removing waste made by cells is excretion."},{"id":"D30-4","topic":1,"q":"State the function of the incisor teeth.","marks":3,"need":1,"pts":[{"a":"Cutting (biting) food","accept":["to bite food","they slice food","cutting food into pieces"],"k":[{"w":["cut"],"n":1},{"w":["cutt"],"n":1},{"w":["bite"],"n":1},{"w":["biting"],"n":1},{"w":["slice"],"n":1},{"w":["snip"],"n":1}]}],"right":"Incisors cut and bite food.","wrong":["They tear and grip meat","They grind and crush food","They mix food with saliva"],"why":"Incisors are the flat, chisel-shaped teeth at the front. They cut and bite off pieces of food; canines tear, and premolars and molars grind."},{"id":"D30-5","topic":1,"q":"State the function of the canine teeth.","marks":3,"need":1,"pts":[{"a":"Tearing (gripping) food","accept":["they rip food","to grip and tear meat","piercing food"],"k":[{"w":["tear"],"n":1},{"w":["rip"],"n":1},{"w":["ripp"],"n":1},{"w":["grip"],"n":1},{"w":["pierc"],"n":1}]}],"right":"Canines tear and grip food.","wrong":["They cut and bite food","They grind and crush food","They push food to the back of the mouth"],"why":"Canines are the pointed teeth beside the incisors. They tear and grip food; they are much longer in meat-eaters such as dogs."},{"id":"D30-6","topic":1,"q":"State the function of the premolars and molars.","marks":3,"need":1,"pts":[{"a":"Grinding (crushing) food","accept":["they crush food","chewing food into small pieces","they mash food"],"k":[{"w":["grind"],"n":1},{"w":["crush"],"n":1},{"w":["chew"],"n":1},{"w":["mash"],"n":1}]}],"right":"They grind and crush food.","wrong":["They cut and bite food","They tear and grip food","They hold food while it is swallowed"],"why":"Premolars and molars are the broad back teeth with cusps. They grind and crush food into small pieces, which gives enzymes a larger surface area."},{"id":"D30-7","topic":2,"q":"Describe how the stomach breaks down food mechanically.","marks":6,"need":2,"pts":[{"a":"Its muscular walls contract: churning","accept":["the stomach wall churns the food","muscles in the wall contract and squeeze the food","churning"],"k":[{"w":["churn"],"n":1},{"w":["muscle","contract"],"n":2},{"w":["muscle","wall"],"n":2},{"w":["squeez"],"n":1}]},{"a":"mixing the food with gastric juice into a liquid (chyme)","accept":["turns the food into chyme","mixes the food with acid and enzymes","makes it into a creamy liquid"],"k":[{"w":["chyme"],"n":1},{"w":["liquid"],"n":1},{"w":["mix","juice"],"n":2},{"w":["mix","acid"],"n":2},{"w":["mix","enzym"],"n":2},{"w":["mix","pepsin"],"n":2}]}],"right":"Its muscular walls churn the food, mixing it with gastric juice.","wrong":["Pepsin breaks proteins down into peptides","Hydrochloric acid kills the bacteria in the food","Bile emulsifies the fat into small droplets"],"why":"Mechanical breakdown changes the size of the pieces, not the molecules: the stomach's muscle layers contract to churn the food, mixing it with gastric juice into a liquid called chyme."},{"id":"D30-8","topic":2,"q":"Is churning in the stomach mechanical or chemical digestion? Explain your answer.","marks":6,"need":2,"pts":[{"a":"Mechanical","accept":["physical digestion"],"k":[{"w":["mechanic"],"n":1},{"w":["physic"],"n":1}]},{"a":"It breaks food into smaller pieces without changing the molecules (no enzymes involved)","accept":["it breaks food into small bits","no enzymes are used","the food is not changed chemically","it increases the surface area of the food"],"k":[{"w":["small","piec"],"n":2},{"w":["small","bit"],"n":2},{"w":["small","particl"],"n":2},{"w":["no","enzym"],"n":2},{"w":["without","enzym"],"n":2},{"w":["not","chemic"],"n":2},{"w":["surfac","area"],"n":2}]}],"right":"Mechanical: it breaks food into smaller pieces without using enzymes.","wrong":["Chemical: pepsin breaks the protein into peptides","Chemical: the acid breaks the food into smaller pieces","Mechanical: enzymes break the large molecules into small ones"],"why":"Churning only breaks food into smaller pieces and mixes it; no bonds are broken. Chemical digestion is done by enzymes such as pepsin, which break the molecules themselves."},{"id":"D30-9","topic":2,"q":"Explain how churning in the stomach helps pepsin to digest protein.","marks":3,"need":1,"pts":[{"a":"It mixes the food with gastric juice (pepsin), so the enzyme reaches all the food","accept":["it mixes pepsin with the food","it breaks food into smaller pieces, giving a larger surface area for pepsin","it brings the enzyme into contact with the food"],"k":[{"w":["mix","juice"],"n":2},{"w":["mix","pepsin"],"n":2},{"w":["mix","enzym"],"n":2},{"w":["mix","acid"],"n":2},{"w":["surfac","area"],"n":2},{"w":["contact"],"n":1}]}],"right":"It mixes the food with gastric juice, so pepsin reaches all of it.","wrong":["It makes the stomach alkaline, the pH pepsin needs","It absorbs the peptides into the blood","It adds bile, which emulsifies the protein"],"why":"Churning mixes the food thoroughly with gastric juice, so pepsin and the acid reach every part of it, and the smaller pieces give the enzyme a larger surface area."},{"id":"D30-10","topic":3,"q":"Name the enzyme that begins the digestion of starch in the mouth, and the product it forms.","marks":6,"need":2,"pts":[{"a":"(Salivary) amylase","accept":["salivary amylase","ptyalin"],"k":[{"w":["amylase"],"n":1},{"w":["ptyalin"],"n":1}]},{"a":"Maltose","accept":[],"k":[{"w":["maltose"],"n":1}]}],"right":"Salivary amylase, which breaks starch down into maltose.","wrong":["Pepsin, which breaks it down into peptides","Lipase, which breaks it down into fatty acids and glycerol","Salivary amylase, which breaks it down into amino acids"],"why":"Saliva contains amylase, which works at about pH 7 and breaks starch into the sugar maltose. Pepsin acts on protein and lipase on fat."},{"id":"D30-11","topic":3,"q":"Explain why salivary amylase stops working when food reaches the stomach.","marks":3,"need":1,"pts":[{"a":"The stomach is acidic (about pH 2), which denatures amylase (its optimum is about pH 7)","accept":["the pH is too low for it","the acid denatures the enzyme","it is denatured by the hydrochloric acid","the pH in the stomach is about 2"],"k":[{"w":["acid"],"n":1},{"w":["denatur"],"n":1},{"w":["low","ph"],"n":2},{"w":["lower","ph"],"n":2},{"w":["ph","2"],"n":2},{"w":["ph","1"],"n":2}]}],"right":"The stomach is too acidic, so the amylase is denatured.","wrong":["There is no starch left by the time food reaches the stomach","The stomach is too cold for amylase to work","Bile from the liver breaks the amylase down"],"why":"Amylase works best at about pH 7. The hydrochloric acid in the stomach gives about pH 2, which denatures it, so starch digestion only starts again in the duodenum."},{"id":"D30-12","topic":3,"q":"Starch digestion is completed in the small intestine. Name the gland that makes the amylase that acts there, and the final product that is absorbed.","marks":6,"need":2,"pts":[{"a":"Pancreas","accept":["the pancreatic gland"],"k":[{"w":["pancrea"],"n":1}]},{"a":"Glucose","accept":[],"k":[{"w":["glucose"],"n":1}]}],"right":"The pancreas; the final product absorbed is glucose.","wrong":["The salivary glands; maltose is absorbed","The liver; glucose is absorbed","The pancreas; starch is absorbed whole"],"why":"Pancreatic juice brings amylase into the duodenum to finish breaking starch into maltose, which is then broken into glucose, the sugar absorbed into the villi."},{"id":"D30-13","topic":3,"q":"Food enters the duodenum at about pH 2, but the duodenum is about pH 8. Explain how the pH is raised.","marks":6,"need":2,"pts":[{"a":"Bile and pancreatic juice are added","accept":["bile from the gall bladder","pancreatic juice"],"k":[{"w":["bile"],"n":1},{"w":["pancrea"],"n":1}]},{"a":"They are alkaline (contain sodium hydrogencarbonate), which neutralises the acid","accept":["they neutralise the stomach acid","they are alkaline","sodium hydrogencarbonate neutralises the acid","they contain bicarbonate"],"k":[{"w":["neutralis"],"n":1},{"w":["alkal"],"n":1},{"w":["hydrogencarbon"],"n":1},{"w":["bicarbon"],"n":1}]}],"right":"Bile and pancreatic juice are alkaline, so they neutralise the acid.","wrong":["The duodenum absorbs the hydrochloric acid into the blood","Pepsin uses up the acid as it digests protein","Bile adds more acid, which kills bacteria"],"why":"Bile and pancreatic juice contain sodium hydrogencarbonate, an alkali that neutralises the stomach acid. This gives the pH of about 8 that lipase and pancreatic amylase need."},{"id":"D30-14","topic":4,"q":"What is meant by deamination?","marks":3,"need":1,"pts":[{"a":"Removal of the amino group from (excess) amino acids in the liver, forming urea","accept":["breaking down spare amino acids to form urea","removing the nitrogen part of an amino acid","the amine group is removed from an amino acid","the NH2 group is removed from amino acids"],"k":[{"w":["amino","remov"],"n":2},{"w":["nitrogen","remov"],"n":2},{"w":["nh2","remov"],"n":2},{"w":["amino","urea"],"n":2},{"w":["nitrogen","urea"],"n":2}]}],"right":"Removing the amino group from spare amino acids, which forms urea.","wrong":["Joining amino acids together to make proteins","Removing urea from the blood in the kidneys","Breaking down proteins into amino acids in the stomach"],"why":"In the liver, the nitrogen-containing amino group is removed from amino acids the body does not need. It is turned into urea, which the kidneys excrete."},{"id":"D30-15","topic":4,"q":"Describe what happens to excess amino acids in the liver.","marks":6,"need":2,"pts":[{"a":"They are deaminated: the amino (nitrogen) group is removed","accept":["deamination","the nitrogen is removed","the amine group is removed"],"k":[{"w":["deamin"],"n":1},{"w":["amino","remov"],"n":2},{"w":["nitrogen","remov"],"n":2}]},{"a":"The amino group is converted into urea","accept":["urea is formed","it makes urea"],"k":[{"w":["urea"],"n":1}]},{"a":"The rest of the molecule is used for energy (respiration)","accept":["the rest is respired","the remainder is used to release energy"],"k":[{"w":["energy"],"n":1},{"w":["respir"],"n":1}]}],"right":"They are deaminated, forming urea, and the rest is used for energy.","wrong":["They are stored in the liver until the body needs them","They are excreted unchanged in the urine","They are turned into urea and stored in the gall bladder"],"why":"The body cannot store amino acids. The liver removes the amino group (deamination), which forms urea; the rest of the molecule is respired for energy."},{"id":"D30-16","topic":4,"q":"Explain why the body deaminates excess amino acids.","marks":3,"need":1,"pts":[{"a":"Amino acids (protein) cannot be stored in the body","accept":["the body has no store for amino acids","they can't be stored","the body is unable to store protein","the body does not store amino acids"],"k":[{"w":["cannot","stor"],"n":2},{"w":["not","stor"],"n":2},{"w":["no","stor"],"n":2}]}],"right":"Amino acids cannot be stored in the body, so spare ones are broken down.","wrong":["So they can be stored as glycogen for later","So the liver can make bile from them","So the kidneys can turn them into urea"],"why":"Unlike glucose (stored as glycogen) and fat, amino acids cannot be stored. Spare ones are deaminated in the liver: urea is formed and the rest is used for energy."},{"id":"D30-17","topic":5,"q":"State what happens to absorbed glucose in the liver when the body does not need it straight away.","marks":3,"need":1,"pts":[{"a":"It is converted to glycogen and stored","accept":["stored as glycogen","made into glycogen"],"k":[{"w":["glycogen"],"n":1}]}],"right":"It is converted into glycogen and stored in the liver.","wrong":["It is converted into glucagon and stored","It is converted into starch and stored","It is deaminated, forming urea"],"why":"Glucose reaches the liver in the hepatic portal vein. The liver (and muscle) stores spare glucose as glycogen; starch is the store in plants, and glucagon is a hormone."},{"id":"D30-18","topic":5,"q":"Explain why it is useful for the liver to store glucose as glycogen.","marks":3,"need":1,"pts":[{"a":"Glucose can be released when needed (between meals), keeping the blood glucose level constant","accept":["it keeps the blood sugar level steady","glycogen can be released as glucose when needed","it is a reserve of energy","it keeps blood glucose stable"],"k":[{"w":["constant"],"n":1},{"w":["steady"],"n":1},{"w":["stabl"],"n":1},{"w":["level","blood"],"n":2},{"w":["releas","need"],"n":2},{"w":["reserv"],"n":1},{"w":["between","meal"],"n":2}]}],"right":"Glucose can be released later, keeping the blood glucose level steady.","wrong":["So the liver can turn the glucose into urea","So the glucose can be excreted in the urine","So the liver can use it to make bile"],"why":"Between meals, glycogen is broken back down to glucose and released into the blood, so cells always have glucose for respiration and the blood glucose level stays steady."},{"id":"D30-19","topic":5,"q":"Describe the route taken by a glucose molecule from the ileum to the liver.","marks":6,"need":2,"pts":[{"a":"It is absorbed into the blood capillaries of a villus","accept":["it passes into the capillaries in the villi","into the blood in the villi"],"k":[{"w":["capillar"],"n":1},{"w":["blood","villi"],"n":2}]},{"a":"It is carried in the hepatic portal vein to the liver","accept":["through the portal vein"],"k":[{"w":["portal"],"n":1}]}],"right":"Into the blood capillaries of the villi, then along the hepatic portal vein.","wrong":["Into the lacteals of the villi, then along the lymph vessels","Into the capillaries of the villi, then along the hepatic artery","Into the lacteals, then along the hepatic vein"],"why":"Glucose passes through the thin wall of a villus into its blood capillaries. These join the hepatic portal vein, which carries the food-rich blood straight to the liver."},{"id":"D30-20","topic":6,"q":"Describe how faeces are formed in the large intestine.","marks":6,"need":2,"pts":[{"a":"Water is absorbed from the undigested material (in the colon)","accept":["water is reabsorbed into the blood","most of the water is taken back into the blood"],"k":[{"w":["water","absorb"],"n":2},{"w":["water","reabsorb"],"n":2},{"w":["water","back","blood"],"n":3}]},{"a":"leaving undigested food (fibre), dead cells and bacteria","accept":["what is left is mainly fibre and bacteria","the remaining undigested food, dead cells and bacteria"],"k":[{"w":["undigest"],"n":1},{"w":["fibre"],"n":1},{"w":["cellulose"],"n":1},{"w":["bacteri"],"n":1},{"w":["dead","cell"],"n":2}]}],"right":"Water is absorbed, leaving undigested fibre, dead cells and bacteria.","wrong":["Enzymes digest the remaining fat into fatty acids","Bile turns the leftover food solid","Water is added to the undigested food to soften it"],"why":"As the undigested remains move through the colon, most of the water is absorbed into the blood. What is left (fibre, dead gut cells and bacteria) forms semi-solid faeces."},{"id":"D30-21","topic":6,"q":"Name the part of the alimentary canal where faeces are stored before egestion.","marks":3,"need":1,"pts":[{"a":"Rectum","accept":[],"k":[{"w":["rectum"],"n":1}]}],"right":"In the rectum","wrong":["In the appendix","In the anus","In the gall bladder"],"why":"The rectum is the last part of the large intestine. It holds the faeces until they are egested through the anus."},{"id":"D30-22","topic":6,"q":"Name the opening through which faeces leave the body.","marks":3,"need":1,"pts":[{"a":"Anus","accept":["the anal opening"],"k":[{"w":["anus"],"n":1},{"w":["anal"],"n":1}]}],"right":"The anus","wrong":["The rectum","The urethra","The colon"],"why":"Faeces leave through the anus, at the end of the rectum: this is egestion. A ring of muscle keeps the anus closed until then. The urethra carries urine."},{"id":"D30-23","topic":7,"q":"Explain why teenagers need more protein in their diet than elderly people.","marks":3,"need":1,"pts":[{"a":"Teenagers are still growing: protein is needed to make new cells (tissue, muscle)","accept":["for growth","they are growing and need to build new cells","to make new tissue"],"k":[{"w":["grow"],"n":1},{"w":["new","cell"],"n":2},{"w":["new","tissu"],"n":2}]}],"right":"Teenagers are still growing, and protein is needed to make new cells.","wrong":["Protein is the main source of energy for teenagers","Protein is stored as fat to keep teenagers warm","Elderly people cannot digest protein at all"],"why":"Protein gives the amino acids used to build new cells and tissues. Teenagers are growing fast, so they need more for their size; adults need it mainly for repair."},{"id":"D30-24","topic":7,"q":"Explain why a very active person needs more carbohydrate in their diet than an inactive person.","marks":3,"need":1,"pts":[{"a":"They use more energy, and carbohydrate (glucose) is the main source of energy for respiration","accept":["carbohydrates give energy for exercise","more glucose is needed for respiration","to fuel their muscles"],"k":[{"w":["energy"],"n":1},{"w":["respir"],"n":1},{"w":["fuel"],"n":1}]}],"right":"They use more energy, and carbohydrate is the body's main energy source.","wrong":["Carbohydrate builds and repairs their muscles","Carbohydrate replaces the salt lost in sweat","Carbohydrate makes their bones stronger"],"why":"Muscles get their energy by respiring glucose. A very active person respires more, so needs more carbohydrate; an inactive person who eats too much stores the extra as fat."},{"id":"D30-25","topic":7,"q":"Explain why teenage girls and women need more iron in their diet than men.","marks":3,"need":1,"pts":[{"a":"To replace the blood (haemoglobin) lost in menstruation (periods)","accept":["to replace blood lost in periods","they lose blood each month in menstruation","to make extra blood during pregnancy"],"k":[{"w":["blood","lose"],"n":2},{"w":["menstru"],"n":1},{"w":["period"],"n":1},{"w":["pregnan"],"n":1}]}],"right":"Iron makes haemoglobin, and it replaces the blood lost during periods.","wrong":["Iron is needed to build strong bones and teeth","Iron helps them to digest fat","Iron is needed to make the hormone oestrogen"],"why":"Iron is part of haemoglobin in red blood cells. Females lose blood each month in menstruation (and make extra blood in pregnancy), so they need more iron to avoid anaemia."},{"id":"D30-26","topic":7,"q":"Give two reasons why a balanced diet must include enough water.","marks":6,"need":2,"pts":[{"a":"Water is the solvent (medium) for the chemical reactions in cells","accept":["reactions in cells take place in water","it dissolves substances","most of the cytoplasm is water"],"k":[{"w":["solvent"],"n":1},{"w":["dissolv"],"n":1},{"w":["reaction"],"n":1},{"w":["cytoplasm"],"n":1}]},{"a":"Transport of substances (blood plasma is mostly water)","accept":["it carries food and wastes in the blood","blood plasma is mostly water"],"k":[{"w":["transport"],"n":1},{"w":["plasma"],"n":1},{"w":["carr"],"n":1}]},{"a":"To replace the water lost in urine, sweat and breath (prevents dehydration)","accept":["to prevent dehydration","we lose water in urine and sweat every day"],"k":[{"w":["replac"],"n":1},{"w":["dehydrat"],"n":1},{"w":["water","lose"],"n":2}]},{"a":"Temperature control: sweating cools the body","accept":["sweat cools the body","it controls body temperature"],"k":[{"w":["temperatur"],"n":1},{"w":["cool"],"n":1}]},{"a":"Keeps the faeces soft, preventing constipation","accept":["it prevents constipation","it keeps faeces soft"],"k":[{"w":["constip"],"n":1},{"w":["faeces","soft"],"n":2}]}],"right":"It is the solvent for reactions in cells, and it replaces water lost in sweat.","wrong":["It gives energy, and it builds and repairs muscle","It digests fat, and it makes the stomach acidic","It is stored as glycogen, and it makes bones hard"],"why":"Most of a cell is water: its reactions take place dissolved in water, and blood plasma carries substances. Water is lost every day in urine, sweat and breath, so it must be replaced."},{"id":"D30-27","topic":8,"q":"State one effect on health of a diet high in sugar.","marks":3,"need":1,"pts":[{"a":"Obesity (weight gain), type 2 diabetes or tooth decay","accept":["it can cause tooth decay","it can lead to type 2 diabetes","weight gain","being overweight","holes (cavities) in the teeth"],"k":[{"w":["obes"],"n":1},{"w":["overweight"],"n":1},{"w":["weight","gain"],"n":2},{"w":["diabet"],"n":1},{"w":["decay"],"n":1},{"w":["cavit"],"n":1}]}],"right":"It can cause obesity and tooth decay.","wrong":["It can cause scurvy","It can cause rickets","It can cause anaemia"],"why":"Spare sugar is stored as fat, so a high-sugar diet can lead to obesity and type 2 diabetes, and mouth bacteria turn sugar into acid that decays teeth."},{"id":"D30-28","topic":8,"q":"Explain how a diet high in sugar can cause tooth decay.","marks":6,"need":2,"pts":[{"a":"Bacteria in the mouth (plaque) feed on the sugar","accept":["mouth bacteria use the sugar","bacteria respire the sugar","micro-organisms in plaque feed on sugar"],"k":[{"w":["bacteri"],"n":1},{"w":["microb"],"n":1},{"w":["micro","organism"],"n":2},{"w":["germ"],"n":1}]},{"a":"They produce acid, which dissolves (attacks) the tooth enamel","accept":["acid is made that dissolves the enamel","the acid wears away the enamel"],"k":[{"w":["acid"],"n":1}]}],"right":"Mouth bacteria feed on the sugar and make acid, which dissolves the enamel.","wrong":["Sugar softens the enamel directly","Sugar stops calcium from reaching the teeth","Bacteria in the mouth turn the sugar into alcohol"],"why":"Bacteria in plaque on the teeth respire the sugar and give off acid. The acid dissolves the hard enamel, making holes (cavities): tooth decay."},{"id":"D30-29","topic":8,"q":"A vegan eats no food from animals. Name a nutrient that a vegan must take care to get enough of.","marks":3,"need":1,"pts":[{"a":"Vitamin B12 (or iron, calcium, protein, iodine or vitamin D)","accept":["iron","calcium","protein","iodine","vitamin D","omega-3 fatty acids"],"k":[{"w":["b12"],"n":1},{"w":["iron"],"n":1},{"w":["calcium"],"n":1},{"w":["protein"],"n":1},{"w":["iodin"],"n":1},{"w":["vitamin","d"],"n":2},{"w":["omega"],"n":1}]}],"right":"Vitamin B12, as it is found almost only in animal foods.","wrong":["Vitamin C, found in fruit","Fibre, found in cereals","Carbohydrate, found in bread"],"why":"Vitamin B12 comes almost only from animal foods, so vegans need fortified foods or supplements. Fibre, vitamin C and carbohydrate are easy to get from plants."},{"id":"D30-30","topic":8,"q":"Name a plant food that is a good source of protein for a vegan.","marks":3,"need":1,"pts":[{"a":"Beans, lentils, peas, nuts, seeds or soya (tofu)","accept":["lentils","nuts","tofu","soya beans","chickpeas","peas","peanuts","seeds"],"k":[{"w":["bean"],"n":1},{"w":["lentil"],"n":1},{"w":["pea"],"n":1},{"w":["chickpea"],"n":1},{"w":["peanut"],"n":1},{"w":["nut"],"n":1},{"w":["tofu"],"n":1},{"w":["soya"],"n":1},{"w":["soy"],"n":1},{"w":["seed"],"n":1},{"w":["quinoa"],"n":1}]}],"right":"Beans and lentils are rich in protein.","wrong":["Cheese and yoghurt","Eggs","Apples and oranges"],"why":"Vegans get protein from plants: pulses such as beans, lentils and peas, and nuts, seeds and soya (tofu). Cheese and eggs come from animals, and fruit has little protein."}],"32":[{"id":"D32-1","topic":0,"q":"Name a disease of humans that is caused by a protist.","marks":3,"need":1,"pts":[{"a":"Malaria (caused by Plasmodium), or amoebic dysentery, or sleeping sickness","accept":["Plasmodium","amoebic dysentery","sleeping sickness"],"k":[{"w":["malaria"],"n":1},{"w":["plasmodium"],"n":1},{"w":["amoeb","dysentery"],"n":2},{"w":["sleep","sick"],"n":2}]}],"right":"Malaria, which is caused by the protist Plasmodium","wrong":["Tuberculosis (TB)","Athlete's foot","Measles"],"why":"Malaria is caused by Plasmodium, a single-celled protist that a mosquito passes into the blood. TB is caused by a bacterium, athlete's foot by a fungus and measles by a virus."},{"id":"D32-2","topic":0,"q":"Tapeworms are parasitic animals that live in the human intestine. State how a person usually becomes infected with a tapeworm.","marks":3,"need":1,"pts":[{"a":"By eating raw or undercooked meat (pork, beef or fish) that contains tapeworm larvae (cysts)","accept":["eating undercooked pork","eating raw meat with tapeworm cysts in it","eating meat that is not cooked properly"],"k":[{"w":["undercook"],"n":1},{"w":["uncook"],"n":1},{"w":["raw","meat"],"n":2},{"w":["raw","pork"],"n":2},{"w":["raw","beef"],"n":2},{"w":["raw","fish"],"n":2},{"w":["not","cook","meat"],"n":3},{"w":["not","cook","pork"],"n":3},{"w":["not","cook","beef"],"n":3},{"w":["meat","larva"],"n":2},{"w":["meat","cyst"],"n":2},{"w":["hasnt","cook","meat"],"n":3},{"w":["isnt","cook","meat"],"n":3},{"w":["wasnt","cook","meat"],"n":3},{"w":["infect","meat"],"n":2},{"w":["infect","pork"],"n":2},{"w":["infect","beef"],"n":2},{"w":["contaminat","meat"],"n":2}]}],"right":"By eating raw or undercooked meat that contains tapeworm larvae","wrong":["By being bitten by an infected mosquito","By breathing in droplets when an infected person coughs","By touching an infected person's skin"],"why":"Tapeworm larvae live in the muscle of infected pigs, cattle or fish. Eating that meat raw or undercooked lets them reach the gut, so cooking meat thoroughly prevents it."},{"id":"D32-3","topic":1,"q":"Name a disease of humans that is caused by a fungus.","marks":3,"need":1,"pts":[{"a":"Athlete's foot, or ringworm, or thrush","accept":["ringworm","thrush","tinea"],"k":[{"w":["athlete"],"n":1},{"w":["ringworm"],"n":1},{"w":["thrush"],"n":1},{"w":["tinea"],"n":1}]}],"right":"Athlete's foot","wrong":["Tuberculosis (TB)","Malaria","The common cold"],"why":"Athlete's foot is caused by a fungus that grows on warm, damp skin between the toes. TB is caused by a bacterium, malaria by a protist and the common cold by a virus."},{"id":"D32-4","topic":1,"q":"Ringworm is a skin infection of humans and animals. What type of organism causes ringworm?","marks":3,"need":1,"pts":[{"a":"A fungus","accept":["fungi","a fungal infection","a mould"],"k":[{"w":["fung"],"n":1},{"w":["mould"],"n":1}]}],"right":"It is caused by a fungus","wrong":["A parasitic worm that lives in the skin","A bacterium","A virus"],"why":"Despite its name, ringworm is not a worm: it is a fungus that grows outwards through the skin, leaving a red ring. It is treated with antifungal cream."},{"id":"D32-5","topic":2,"q":"State the role of natural killer (NK) cells in the body.","marks":3,"need":1,"pts":[{"a":"They destroy body cells infected by viruses, and cancer (tumour) cells","accept":["kill virus-infected cells","destroy cancer cells","kill tumour cells","attack infected cells"],"k":[{"w":["kill","infect"],"n":2},{"w":["destroy","infect"],"n":2},{"w":["attack","infect"],"n":2},{"w":["burst","infect"],"n":2},{"w":["kill","cancer"],"n":2},{"w":["destroy","cancer"],"n":2},{"w":["attack","cancer"],"n":2},{"w":["kill","tumour"],"n":2},{"w":["destroy","tumour"],"n":2}]}],"right":"They destroy body cells that are infected by viruses, and cancer cells","wrong":["They make antibodies against one specific antigen","They engulf and digest bacteria by phagocytosis","They remember an antigen so that a second attack is beaten fast"],"why":"NK cells are white blood cells that recognise body cells that are infected with a virus, or cancerous, and make them die. Antibodies come from B cells, and engulfing is done by phagocytes."},{"id":"D32-6","topic":2,"q":"Natural killer (NK) cells are part of the innate (general) immune system. Explain why.","marks":3,"need":1,"pts":[{"a":"They are non-specific: they attack any infected cell without needing to recognise a particular antigen","accept":["they are non-specific","they attack any infected cell","they do not target one specific antigen"],"k":[{"w":["non","specific"],"n":2},{"w":["nonspecific"],"n":1},{"w":["not","specific"],"n":2},{"w":["any","infect"],"n":2},{"w":["any","pathogen"],"n":2},{"w":["all","infect"],"n":2},{"w":["dont","specific"],"n":2},{"w":["without","specific"],"n":2},{"w":["no","specific"],"n":2}]}],"right":"They attack any infected cell: they are not specific to one antigen","wrong":["They make antibodies that fit one particular antigen","They are made in the bone marrow","They form memory cells after an infection"],"why":"The innate system is always ready and is not specific: NK cells act on any virus-infected or cancer cell at once, without needing to learn one antigen or making memory cells."},{"id":"D32-7","topic":3,"q":"What is meant by the cell-mediated immune response?","marks":3,"need":1,"pts":[{"a":"T lymphocytes (killer T cells) attack and destroy infected body cells directly, without antibodies","accept":["killer T cells destroy infected cells","T cells kill body cells infected by a virus","T cells attack infected cells themselves"],"k":[{"w":["t","kill","infect"],"n":3},{"w":["t","destroy","infect"],"n":3},{"w":["t","attack","infect"],"n":3},{"w":["t","burst","infect"],"n":3}]}],"right":"Killer T cells attack and destroy infected body cells directly","wrong":["B lymphocytes make antibodies that bind to antigens in the blood","Phagocytes engulf any pathogen they meet","Memory cells give long-term protection against an antigen"],"why":"In the cell-mediated response the T cells themselves do the work: killer T cells bind to body cells that show viral antigens and burst them with perforin. No antibodies are involved."},{"id":"D32-8","topic":3,"q":"What is meant by the antibody (humoral) immune response?","marks":3,"need":1,"pts":[{"a":"B lymphocytes make antibodies, which lock onto the antigens of pathogens in the blood and body fluids","accept":["B cells produce antibodies","plasma cells make antibodies against the antigen"],"k":[{"w":["b","antibod"],"n":2},{"w":["plasma","antibod"],"n":2}]}],"right":"B lymphocytes make antibodies that lock onto antigens on the pathogen","wrong":["Killer T cells release perforin to burst infected cells","Phagocytes engulf pathogens and digest them with enzymes","Suppressor T cells switch off the immune response"],"why":"In the humoral response B lymphocytes make antibodies that float in the blood and lymph and bind to antigens on free pathogens, marking them for phagocytes to destroy."},{"id":"D32-9","topic":3,"q":"Distinguish between the roles of B lymphocytes and killer T cells when a virus infects the body.","marks":6,"need":2,"pts":[{"a":"B lymphocytes make antibodies against the virus (the antibody or humoral response)","accept":["B cells produce antibodies","B cells give the humoral response"],"k":[{"w":["b","antibod"],"n":2},{"w":["b","humoral"],"n":2}]},{"a":"Killer T cells destroy the body cells that are infected with the virus (the cell-mediated response)","accept":["killer T cells kill infected cells","T cells destroy infected body cells","T cells give the cell-mediated response"],"k":[{"w":["t","kill","infect"],"n":3},{"w":["t","destroy","infect"],"n":3},{"w":["t","attack","infect"],"n":3},{"w":["t","burst","infect"],"n":3},{"w":["t","cell","mediat"],"n":3}]}],"right":"B cells make antibodies; killer T cells destroy the infected body cells","wrong":["Both make antibodies that bind to the virus","B cells engulf viruses; T cells make memory cells","B cells make antibodies; T cells engulf and digest the virus"],"why":"Antibodies from B cells deal with viruses outside cells. Once a virus is inside a cell, antibodies can't reach it, so killer T cells destroy the infected cell itself."},{"id":"D32-10","topic":4,"q":"Give one example of a disease of humans that is caused by an RNA virus.","marks":3,"need":1,"pts":[{"a":"Influenza (flu), AIDS (HIV), COVID-19, measles, mumps, polio or the common cold","accept":["flu","HIV","COVID-19","measles","the common cold","mumps","polio","Ebola"],"k":[{"w":["flu"],"n":1},{"w":["influenza"],"n":1},{"w":["hiv"],"n":1},{"w":["aid"],"n":1},{"w":["covid"],"n":1},{"w":["coronavirus"],"n":1},{"w":["measl"],"n":1},{"w":["mump"],"n":1},{"w":["polio"],"n":1},{"w":["ebola"],"n":1},{"w":["common","cold"],"n":2},{"w":["rubella"],"n":1}]}],"right":"Influenza (the flu)","wrong":["Chickenpox","Cold sores (herpes)","Tuberculosis (TB)"],"why":"Flu viruses carry their genes as RNA. Chickenpox and cold sores are caused by DNA viruses (herpes viruses), and TB is caused by a bacterium."},{"id":"D32-11","topic":4,"q":"HIV is an RNA virus called a retrovirus. Name the enzyme it uses to make DNA from its RNA.","marks":3,"need":1,"pts":[{"a":"Reverse transcriptase","accept":["reverse transcriptase enzyme"],"k":[{"w":["reverse","transcriptase"],"n":2}]}],"right":"Reverse transcriptase","wrong":["RNA polymerase","DNA ligase","Restriction enzyme"],"why":"A retrovirus works backwards: reverse transcriptase copies its RNA into DNA, which is then inserted into the host cell's DNA. Antiviral drugs for HIV block this enzyme."},{"id":"D32-12","topic":4,"q":"The flu virus is an RNA virus. Explain why a new flu vaccine is needed every year.","marks":6,"need":2,"pts":[{"a":"RNA viruses such as flu mutate quickly (often), because errors are made copying their RNA","accept":["it mutates very fast","the virus mutates often","it has a high rate of mutation"],"k":[{"w":["mutat","quick"],"n":2},{"w":["mutat","fast"],"n":2},{"w":["mutat","often"],"n":2},{"w":["mutat","rapid"],"n":2},{"w":["mutat","frequent"],"n":2},{"w":["mutat","high"],"n":2},{"w":["mutat","year"],"n":2},{"w":["mutat","lot"],"n":2},{"w":["mutat","many"],"n":2},{"w":["mutat","constant"],"n":2},{"w":["mutat","always"],"n":2}]},{"a":"So new strains appear with different antigens, which antibodies and memory cells from last year's vaccine don't recognise","accept":["new strains appear","its antigens change","memory cells do not recognise the new virus"],"k":[{"w":["new","strain"],"n":2},{"w":["antigen","chang"],"n":2},{"w":["differ","antigen"],"n":2},{"w":["new","antigen"],"n":2},{"w":["not","recognis"],"n":2},{"w":["dont","recognis"],"n":2}]}],"right":"Its RNA mutates quickly, so new strains appear with different antigens","wrong":["The antibodies made by the vaccine only last for one year","The flu virus becomes resistant to the vaccine","Memory cells are all destroyed every winter"],"why":"RNA is copied with more mistakes than DNA, so flu mutates fast. New strains have changed antigens that last year's memory cells don't fit, so the vaccine is updated each year."},{"id":"D32-13","topic":5,"q":"A disease has a reproduction number (R value) of 3. What does this mean?","marks":3,"need":1,"pts":[{"a":"On average, each infected person passes the disease on to 3 other people","accept":["each case infects three other people","every infected person passes it on to 3 people","each person infects 3 others on average"],"k":[{"w":["3","other","people"],"n":3},{"w":["three","other","people"],"n":3},{"w":["3","other","person"],"n":3},{"w":["three","other","person"],"n":3},{"w":["3","other","infect"],"n":3},{"w":["three","other","infect"],"n":3},{"w":["pass","3"],"n":2},{"w":["pass","three"],"n":2},{"w":["average","3","people"],"n":3},{"w":["average","three","people"],"n":3},{"w":["infect","3","people","each"],"n":4},{"w":["infect","three","people","each"],"n":4},{"w":["3","new","case"],"n":3},{"w":["three","new","case"],"n":3}]}],"right":"Each infected person passes it on to 3 other people, on average","wrong":["3 people in every 100 have the disease","An infected person stays ill for 3 weeks","The disease kills 3% of the people who catch it"],"why":"R is the average number of people each infected person passes the disease on to. With R = 3, 1 case leads to 3, then 9, then 27: the outbreak grows fast."},{"id":"D32-14","topic":5,"q":"What happens to the number of cases of a disease when its R value stays below 1? Explain why.","marks":6,"need":2,"pts":[{"a":"The number of cases falls and the outbreak dies out","accept":["cases decrease","the outbreak dies out","the number of cases drops"],"k":[{"w":["decreas"],"n":1},{"w":["die","out"],"n":2},{"w":["disappear"],"n":1},{"w":["few","case"],"n":2},{"w":["less","case"],"n":2},{"w":["goe","down"],"n":2},{"w":["go","down"],"n":2},{"w":["going","down"],"n":2},{"w":["went","down"],"n":2}]},{"a":"Each infected person passes it on to fewer than one other person on average","accept":["each person infects less than one other person","each case causes under one new case"],"k":[{"w":["less","one"],"n":2},{"w":["few","one"],"n":2},{"w":["under","one"],"n":2},{"w":["less","1"],"n":2},{"w":["few","1"],"n":2}]}],"right":"Cases fall, as each infected person infects less than one other on average","wrong":["Cases rise, because each person infects more than one other","Cases stay the same, as each person infects exactly one other","Cases fall, because the virus mutates into a weaker strain"],"why":"If each case causes less than one new case, every round of infection is smaller than the last, so the outbreak shrinks and dies out. Above 1, each round is bigger and it grows."},{"id":"D32-15","topic":6,"q":"What is meant by a carrier of an infectious disease?","marks":3,"need":1,"pts":[{"a":"A person who is infected with the pathogen and can pass it on, but has no symptoms","accept":["someone who has the pathogen but shows no symptoms","a person infected without feeling ill","a person who is not ill but can spread it"],"k":[{"w":["no","symptom","infect"],"n":3},{"w":["no","symptom","pathogen"],"n":3},{"w":["no","symptom","pass"],"n":3},{"w":["no","symptom","spread"],"n":3},{"w":["no","symptom","disease"],"n":3},{"w":["not","symptom","infect"],"n":3},{"w":["not","symptom","pathogen"],"n":3},{"w":["not","symptom","pass"],"n":3},{"w":["not","symptom","spread"],"n":3},{"w":["not","symptom","disease"],"n":3},{"w":["without","symptom","infect"],"n":3},{"w":["without","symptom","pathogen"],"n":3},{"w":["without","symptom","pass"],"n":3},{"w":["without","symptom","spread"],"n":3},{"w":["without","symptom","disease"],"n":3},{"w":["doesnt","symptom","infect"],"n":3},{"w":["doesnt","symptom","pathogen"],"n":3},{"w":["doesnt","symptom","pass"],"n":3},{"w":["doesnt","symptom","spread"],"n":3},{"w":["doesnt","symptom","disease"],"n":3},{"w":["dont","symptom","infect"],"n":3},{"w":["dont","symptom","pathogen"],"n":3},{"w":["dont","symptom","pass"],"n":3},{"w":["dont","symptom","spread"],"n":3},{"w":["dont","symptom","disease"],"n":3},{"w":["not","ill","infect"],"n":3},{"w":["not","ill","pathogen"],"n":3},{"w":["not","ill","pass"],"n":3},{"w":["not","ill","spread"],"n":3},{"w":["not","ill","disease"],"n":3},{"w":["without","ill","infect"],"n":3},{"w":["without","ill","pathogen"],"n":3},{"w":["without","ill","pass"],"n":3},{"w":["without","ill","spread"],"n":3},{"w":["without","ill","disease"],"n":3},{"w":["not","sick","infect"],"n":3},{"w":["not","sick","pathogen"],"n":3},{"w":["not","sick","pass"],"n":3},{"w":["not","sick","spread"],"n":3},{"w":["not","sick","disease"],"n":3},{"w":["without","sick","infect"],"n":3},{"w":["without","sick","pathogen"],"n":3},{"w":["without","sick","pass"],"n":3},{"w":["without","sick","spread"],"n":3},{"w":["without","sick","disease"],"n":3},{"w":["healthy","infect"],"n":2},{"w":["healthy","pathogen"],"n":2},{"w":["healthy","pass"],"n":2},{"w":["healthy","spread"],"n":2},{"w":["healthy","disease"],"n":2},{"w":["asymptomatic","infect"],"n":2},{"w":["asymptomatic","pathogen"],"n":2},{"w":["asymptomatic","pass"],"n":2},{"w":["asymptomatic","spread"],"n":2},{"w":["asymptomatic","disease"],"n":2}]}],"right":"A person who has the pathogen and can pass it on, but has no symptoms","wrong":["An animal, such as a mosquito, that carries a pathogen between people","A person who is in hospital with the disease","A person who is immune because they had the disease before"],"why":"A carrier is infected and can spread the pathogen but is not ill, so nobody knows to keep away. An animal like a mosquito that carries a pathogen is called a vector."},{"id":"D32-16","topic":6,"q":"Some people carry a pathogen for years without feeling ill. Explain how this helps the disease to spread.","marks":6,"need":2,"pts":[{"a":"They don't know they are infected, so they don't stay away from others or take precautions","accept":["they are unaware they have it","they do not know they are infected","they don't isolate themselves"],"k":[{"w":["dont","know"],"n":2},{"w":["not","know"],"n":2},{"w":["unaware"],"n":1},{"w":["not","aware"],"n":2},{"w":["not","isolat"],"n":2},{"w":["dont","isolat"],"n":2},{"w":["mix"],"n":1},{"w":["not","stay","away"],"n":3},{"w":["dont","stay","away"],"n":3},{"w":["no","precaution"],"n":2},{"w":["not","precaution"],"n":2},{"w":["dont","precaution"],"n":2}]},{"a":"The pathogen persists in them, so they can infect others over a long period","accept":["the pathogen persists in their body","they can infect people for a long time"],"k":[{"w":["persist"],"n":1},{"w":["long","infect"],"n":2},{"w":["long","pass"],"n":2},{"w":["long","spread"],"n":2},{"w":["year","infect"],"n":2},{"w":["year","pass"],"n":2},{"w":["year","spread"],"n":2}]}],"right":"They don't know they are infected, so they keep passing it on for a long time","wrong":["Their immune system is stronger than other people's","The pathogen mutates inside them into a deadly strain","They take antibiotics, which kill the pathogen"],"why":"A carrier has no symptoms, so they mix freely instead of staying away from others, and because the pathogen persists in them they can infect people for months or years."},{"id":"D32-17","topic":7,"q":"Give one example of chemical resistance, apart from antibiotic resistance in bacteria.","marks":3,"need":1,"pts":[{"a":"Insecticide (pesticide) resistance in insects, fungicide resistance in fungi, herbicide resistance in weeds, or antiviral resistance in viruses","accept":["fungicide resistance","weeds resistant to herbicide","HIV resistant to antiviral drugs","fungi resistant to antifungal drugs","pesticide resistance"],"k":[{"w":["insecticid"],"n":1},{"w":["pesticid"],"n":1},{"w":["fungicid"],"n":1},{"w":["herbicid"],"n":1},{"w":["weedkill"],"n":1},{"w":["antiviral"],"n":1},{"w":["antifungal"],"n":1},{"w":["antimalari"],"n":1}]}],"right":"Mosquitoes becoming resistant to the insecticides used to kill them","wrong":["Bacteria becoming resistant to penicillin","Viruses becoming resistant to antibiotics","People becoming immune to measles after a vaccine"],"why":"Any chemical that kills a pest or pathogen selects for resistant mutants: insecticides in mosquitoes, fungicides in fungi, herbicides in weeds and antivirals in viruses."},{"id":"D32-18","topic":7,"q":"A farmer sprays the same insecticide every year and it stops working. Explain how the insects became resistant to it.","marks":6,"need":2,"pts":[{"a":"A few insects had a mutation (variation) that made them resistant","accept":["a mutation made some insects resistant","some insects had a variation that made them resistant"],"k":[{"w":["mutat"],"n":1},{"w":["variat","resistant"],"n":2},{"w":["some","resistant"],"n":2},{"w":["few","resistant"],"n":2}]},{"a":"The resistant ones survived the spray and reproduced, passing the resistance gene on to their offspring","accept":["the resistant insects survived and reproduced","they passed on the resistance gene","their offspring inherited the resistance"],"k":[{"w":["surviv","reproduc"],"n":2},{"w":["surviv","breed"],"n":2},{"w":["surviv","bred"],"n":2},{"w":["surviv","multipl"],"n":2},{"w":["natur","select","surviv"],"n":3},{"w":["pass","gene"],"n":2},{"w":["offspring","resistant"],"n":2},{"w":["inherit"],"n":1}]}],"right":"A few had a mutation for resistance; they survived the spray and reproduced","wrong":["The insects got used to the spray and built up immunity to it","The spray caused mutations in every insect that made them resistant","The insects made antibodies against the insecticide"],"why":"The spray doesn't cause resistance: it kills the insects without the resistance mutation. The few resistant ones survive, breed and pass on the gene, so the population becomes resistant."},{"id":"D32-19","topic":8,"q":"State one way in which the movement of people can help an infectious disease to spread.","marks":3,"need":1,"pts":[{"a":"Infected people (who may have no symptoms yet) carry the pathogen to new places or countries, where others catch it","accept":["travellers bring the pathogen to new countries","infected people carry it to other areas","air travel spreads it around the world quickly"],"k":[{"w":["new","countr"],"n":2},{"w":["new","place"],"n":2},{"w":["new","area"],"n":2},{"w":["new","region"],"n":2},{"w":["other","countr"],"n":2},{"w":["other","place"],"n":2},{"w":["other","area"],"n":2},{"w":["carry","pathogen"],"n":2},{"w":["bring","pathogen"],"n":2},{"w":["spread","world"],"n":2}]}],"right":"Infected people carry the pathogen to new countries, where others catch it","wrong":["People who travel build up immunity to every disease","Moving about makes the pathogen mutate faster","Pathogens die when they are moved to a different climate"],"why":"People travel far and fast, often before symptoms show, so an infected traveller can bring a pathogen to a place where nobody is immune and start a new outbreak there."},{"id":"D32-20","topic":8,"q":"Ash dieback is a fungal disease of ash trees. Explain how importing young ash plants from abroad could bring the disease into a new country.","marks":6,"need":2,"pts":[{"a":"The imported plants (or the soil with them) may already be infected, carrying the fungus or its spores","accept":["the plants carry fungal spores","the imported plants are already infected","the plants carry the pathogen"],"k":[{"w":["carry","spore"],"n":2},{"w":["carry","fung"],"n":2},{"w":["carry","pathogen"],"n":2},{"w":["already","infect"],"n":2},{"w":["spore"],"n":1},{"w":["plant","infect"],"n":2},{"w":["import","infect"],"n":2},{"w":["import","diseas"],"n":2}]},{"a":"The fungus then spreads to the native ash trees, which have no resistance to it","accept":["it spreads to native trees","the native trees have no resistance","local ash trees are not resistant to it"],"k":[{"w":["spread","native"],"n":2},{"w":["spread","local"],"n":2},{"w":["no","resist"],"n":2},{"w":["not","resist"],"n":2},{"w":["native","infect"],"n":2},{"w":["local","infect"],"n":2}]}],"right":"They carry fungal spores that spread to native ash with no resistance","wrong":["The imported plants are weaker, so they die and rot","The ash trees mutate when they are moved to a new climate","Insects from abroad eat the leaves of the trees"],"why":"Young plants can look healthy while carrying the fungus. Once planted, its spores blow onto native ash trees, which have never met the disease and so have no resistance to it."},{"id":"D32-21","topic":9,"q":"What is meant by a novel virus?","marks":3,"need":1,"pts":[{"a":"A new virus that has not been seen before in that species, often one that has jumped from animals to humans","accept":["a new virus","a virus never seen before in humans","a virus that has jumped from animals to humans"],"k":[{"w":["new","virus"],"n":2},{"w":["not","seen","before"],"n":3},{"w":["never","seen"],"n":2},{"w":["not","found","before"],"n":3},{"w":["jump","animal"],"n":2}]}],"right":"A new virus that has never been seen before in that species","wrong":["A virus that mutates very quickly, like the flu","A virus that only infects bacteria","A virus that contains DNA instead of RNA"],"why":"A novel virus is new to a species, often after it spills over from animals, as SARS-CoV-2 did. Nobody has immunity to it, so it can spread fast."},{"id":"D32-22","topic":9,"q":"Name one novel virus that has spread from animals into humans.","marks":3,"need":1,"pts":[{"a":"SARS-CoV-2 (COVID-19), bird flu, swine flu, Ebola, MERS, Zika or HIV","accept":["SARS-CoV-2","COVID-19","bird flu","swine flu","Ebola","MERS","Zika virus","H5N1"],"k":[{"w":["sar"],"n":1},{"w":["covid"],"n":1},{"w":["coronavirus"],"n":1},{"w":["bird","flu"],"n":2},{"w":["avian","flu"],"n":2},{"w":["swine","flu"],"n":2},{"w":["ebola"],"n":1},{"w":["mer"],"n":1},{"w":["zika"],"n":1},{"w":["h5n1"],"n":1},{"w":["h1n1"],"n":1},{"w":["hiv"],"n":1},{"w":["nipah"],"n":1},{"w":["mpox"],"n":1}]}],"right":"SARS-CoV-2, the coronavirus that causes COVID-19","wrong":["The common cold virus","Measles","Tuberculosis (TB)"],"why":"SARS-CoV-2 is thought to have spilled over from bats into humans in 2019. Measles and the cold have been in people for centuries, and TB is a bacterium, not a virus."},{"id":"D32-23","topic":9,"q":"Explain why it is important for society to know about emerging diseases.","marks":3,"need":1,"pts":[{"a":"So they can be found and controlled early, before an epidemic or pandemic, and vaccines and treatments developed in time","accept":["to stop a pandemic","so the spread can be controlled","so vaccines can be developed in time","to be prepared for an outbreak"],"k":[{"w":["early"],"n":1},{"w":["pandemic"],"n":1},{"w":["epidemic"],"n":1},{"w":["prepar"],"n":1},{"w":["vaccin","develop"],"n":2},{"w":["control","spread"],"n":2},{"w":["stop","spread"],"n":2},{"w":["prevent","spread"],"n":2},{"w":["limit","spread"],"n":2},{"w":["reduc","spread"],"n":2},{"w":["slow","spread"],"n":2}]}],"right":"So outbreaks are found and controlled early, before they become a pandemic","wrong":["So that people never catch any disease again","So that antibiotics can be given to everyone with a virus","So that doctors know which bacteria cause the common cold"],"why":"A new disease caught early can be contained by testing and isolation, and work on vaccines and treatments can start, before it becomes an epidemic or a pandemic."},{"id":"D32-24","topic":10,"q":"What is meant by an autoimmune disease?","marks":3,"need":1,"pts":[{"a":"A disease in which the immune system attacks the body's own cells (it treats self as foreign)","accept":["the immune system attacks the body's own tissues","the body's own cells are treated as foreign","when your antibodies attack your own body"],"k":[{"w":["attack","own","cell"],"n":3},{"w":["attack","own","tissue"],"n":3},{"w":["attack","own","body"],"n":3},{"w":["destroy","own","cell"],"n":3},{"w":["self","foreign"],"n":2},{"w":["own","foreign"],"n":2},{"w":["attack","itself"],"n":2},{"w":["attack","self"],"n":2}]}],"right":"A disease in which the immune system attacks the body's own cells","wrong":["A disease caused by a virus that attacks the immune system, such as HIV","An allergy: the immune system overreacts to harmless pollen","A disease the body can cure by itself without medicine"],"why":"Normally lymphocytes ignore the body's own antigens. In an autoimmune disease they treat self as foreign and attack it, e.g. the insulin-making cells in type 1 diabetes."},{"id":"D32-25","topic":10,"q":"Name one autoimmune disease.","marks":3,"need":1,"pts":[{"a":"Type 1 diabetes, rheumatoid arthritis, multiple sclerosis, coeliac disease or lupus","accept":["type one diabetes","rheumatoid arthritis","multiple sclerosis (MS)","coeliac disease","lupus"],"k":[{"w":["type","1","diabet"],"n":3},{"w":["type","one","diabet"],"n":3},{"w":["type","i","diabet"],"n":3},{"w":["rheumatoid"],"n":1},{"w":["multiple","sclerosis"],"n":2},{"w":["coeliac"],"n":1},{"w":["lupus"],"n":1},{"w":["ms"],"n":1},{"w":["grave"],"n":1},{"w":["hashimoto"],"n":1},{"w":["psoriasis"],"n":1}]}],"right":"Type 1 diabetes","wrong":["Type 2 diabetes","AIDS, caused by HIV","Hay fever"],"why":"In type 1 diabetes the immune system destroys the pancreas cells that make insulin. Type 2 diabetes is not autoimmune, AIDS is caused by a virus and hay fever is an allergy."},{"id":"D32-26","topic":10,"q":"In type 1 diabetes, which cells of the body are attacked by the immune system?","marks":3,"need":1,"pts":[{"a":"The insulin-making (beta) cells of the pancreas (in the islets of Langerhans)","accept":["cells in the pancreas","the islets of Langerhans","beta cells","the cells that make insulin"],"k":[{"w":["pancrea"],"n":1},{"w":["islet"],"n":1},{"w":["langerhan"],"n":1},{"w":["beta"],"n":1},{"w":["insulin","make"],"n":2}]}],"right":"The cells in the pancreas that make insulin","wrong":["The liver cells that store glucose as glycogen","The red blood cells that carry glucose","The cells of the small intestine that absorb glucose"],"why":"Lymphocytes destroy the beta cells in the islets of the pancreas, so little or no insulin is made and blood glucose stays too high. People with it need insulin injections."},{"id":"D32-27","topic":11,"q":"Apart from vaccines and medicines, give two ways to control the spread of a new infectious disease.","marks":6,"need":2,"pts":[{"a":"Isolating infected people (quarantine)","accept":["quarantine","isolation of cases"],"k":[{"w":["isolat"],"n":1},{"w":["quarantin"],"n":1}]},{"a":"Contact tracing","accept":["tracing the contacts of infected people"],"k":[{"w":["contact","trac"],"n":2}]},{"a":"Testing and surveillance to find cases early","accept":["testing","surveillance","monitoring cases"],"k":[{"w":["test"],"n":1},{"w":["surveillanc"],"n":1},{"w":["monitor"],"n":1}]},{"a":"Controlling vectors such as mosquitoes (nets, repellent, draining standing water)","accept":["killing mosquitoes","vector control","mosquito nets"],"k":[{"w":["mosquito"],"n":1},{"w":["vector"],"n":1}]},{"a":"Wearing masks (face coverings)","accept":["wearing face masks","face coverings"],"k":[{"w":["mask"],"n":1},{"w":["face","cover"],"n":2}]},{"a":"Good hygiene: washing hands, disinfecting surfaces","accept":["washing hands","good hygiene","hand sanitiser"],"k":[{"w":["wash","hand"],"n":2},{"w":["hygien"],"n":1},{"w":["sanitis"],"n":1},{"w":["disinfect"],"n":1}]},{"a":"Social distancing (avoiding crowds)","accept":["social distancing","avoiding crowded places"],"k":[{"w":["distanc"],"n":1},{"w":["avoid","crowd"],"n":2}]},{"a":"Limiting travel (border controls, lockdown)","accept":["travel bans","border controls","a lockdown"],"k":[{"w":["travel"],"n":1},{"w":["border"],"n":1},{"w":["lockdown"],"n":1}]}],"right":"Isolating infected people and tracing their contacts","wrong":["Isolating infected people and giving everyone antibiotics","Eating a healthy diet and getting plenty of sleep","Keeping warm and drinking plenty of fluids"],"why":"Isolation stops infected people passing it on, and contact tracing finds the people they met before they spread it. Antibiotics don't work on viruses, and a good diet won't stop spread."},{"id":"D32-28","topic":11,"q":"What is meant by contact tracing?","marks":3,"need":1,"pts":[{"a":"Finding the people an infected person has been in close contact with, so they can be tested or isolated","accept":["identifying everyone an infected person has met","finding the people who were in contact with a case"],"k":[{"w":["find","met"],"n":2},{"w":["find","contact"],"n":2},{"w":["find","near"],"n":2},{"w":["identif","met"],"n":2},{"w":["identif","contact"],"n":2},{"w":["identif","near"],"n":2},{"w":["track","down","contact"],"n":3},{"w":["who","contact","infect"],"n":3},{"w":["who","met","infect"],"n":3},{"w":["locat","contact"],"n":2}]}],"right":"Finding everyone an infected person has met, so they can be tested or isolated","wrong":["Testing everyone in the country for the disease","Keeping infected people away from everyone else","Tracking where the mosquitoes that carry the virus breed"],"why":"Contact tracing finds the people an infected person has been near, so they can be tested and isolated before they pass it on. That breaks the chain of spread."},{"id":"D32-29","topic":12,"q":"What type of medicine is used to treat athlete's foot?","marks":3,"need":1,"pts":[{"a":"An antifungal (cream, powder or drug)","accept":["antifungal cream","an anti-fungal powder"],"k":[{"w":["antifungal"],"n":1},{"w":["anti","fung"],"n":2}]}],"right":"An antifungal cream","wrong":["An antibiotic cream","An antiviral drug","A vaccine"],"why":"Athlete's foot is caused by a fungus, so it needs an antifungal, which kills fungi or stops them growing. Antibiotics act on bacteria, and antivirals on viruses."},{"id":"D32-30","topic":12,"q":"Antiviral drugs are used to treat some viral infections. State one way an antiviral drug can work.","marks":3,"need":1,"pts":[{"a":"It stops the virus copying itself (replicating) inside the host cell, or stops it entering or leaving cells","accept":["it stops the virus from replicating","it blocks the virus entering host cells","it prevents new viruses being released","it blocks reverse transcriptase in HIV"],"k":[{"w":["stop","copy"],"n":2},{"w":["stop","replicat"],"n":2},{"w":["stop","reproduc"],"n":2},{"w":["stop","multipl"],"n":2},{"w":["stop","enter"],"n":2},{"w":["stop","release"],"n":2},{"w":["prevent","copy"],"n":2},{"w":["prevent","replicat"],"n":2},{"w":["prevent","reproduc"],"n":2},{"w":["prevent","multipl"],"n":2},{"w":["prevent","enter"],"n":2},{"w":["prevent","release"],"n":2},{"w":["block","copy"],"n":2},{"w":["block","replicat"],"n":2},{"w":["block","enter"],"n":2},{"w":["block","release"],"n":2},{"w":["block","reverse","transcriptase"],"n":3}]}],"right":"It stops the virus from copying itself inside the host cell","wrong":["It kills the virus by breaking down its cell wall","It makes the body produce antibodies against the virus","It stops bacteria from making their cell walls"],"why":"Viruses multiply inside our own cells, so antivirals target virus-only steps: getting into cells, copying viral genes (e.g. reverse transcriptase in HIV) or releasing new viruses."}]};
